INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 2, '물질에 따라 자석에 반발하는 물체를 무엇이라 하는가?', '["비자성체","상자성체","반자성체","강자성체"]'::jsonb, '3', '자성체의 종류:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 3, '도체를 전기 전도도가 좋은 순서대로 나열한 것은?', '["은 $\\rightarrow$ 구리 $\\rightarrow$ 금 $\\rightarrow$ 알루미늄","구리 $\\rightarrow$ 금 $\\rightarrow$ 은 $\\rightarrow$ 알루미늄","금 $\\rightarrow$ 구리 $\\rightarrow$ 알루미늄 $\\rightarrow$ 은","알루미늄 $\\rightarrow$ 금 $\\rightarrow$ 은 $\\rightarrow$ 구리"]'::jsonb, '1', '전기 전도도(도전율)가 높은 순서는 다음과 같습니다:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 4, '전원과 부하가 다같이 $\Delta$결선된 3상 평형 회로가 있다. 상전압이 $200[V]$, 부하 임피던스가 $Z = 6 + j8 [\Omega]$인 경우 선전류는 몇 $[A]$인가? [그림 참고]', '["20","20/\\sqrt{3}","20\\sqrt{3}","10\\sqrt{3}"]'::jsonb, '3', '1. $\Delta$결선의 특징: 선간전압($V_l$) = 상전압($V_p$) = $200[V]$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 5, '공기 중에서 자속 밀도 $3[Wb/m^2]$의 평등 자장 속에 길이 $10[cm]$의 직선 도선을 자장의 방향과 직각으로 놓고 여기에 $4[A]$의 전류를 흐르게 하면 이 도선이 받는 힘은 몇 $[N]$인가?', '["0.5","1.2","2.8","4.2"]'::jsonb, '2', '전자력(플레밍의 왼손 법칙) 공식:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 6, '저항이 $10[\Omega]$인 도체에 $1[A]$의 전류를 10분간 흘렸다면 발생하는 열량은 몇 $[kcal]$인가?', '["69","4","6","6.24"]'::jsonb, '2', '줄(Joule)의 법칙에 의한 열량 $H$:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 7, '다음 회로의 합성 정전 용량 $[\mu F]$은? [그림 참고]', '["5","4","3","2"]'::jsonb, '3', '1. 병렬 부분($2\mu F, 4\mu F$) 합성: $2 + 4 = 6[\mu F]$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 8, '$v = 100 \sin(314t - \pi/6) [V]$인 파형의 주파수는 약 몇 $[Hz]$인가?', '["40","50","60","80"]'::jsonb, '2', '각주파수 $\omega = 2\pi f = 314$ [rad/s]
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 9, '정전 용량 $C[F]$의 콘덴서에 충전된 전하가 $Q = \sqrt{2}Q \sin \omega t [C]$와 같이 변화하도록 하였다면, 이때 콘덴서에 흘러 들어가는 전류의 값은?', '["$i = \\sqrt{2}\\omega Q \\sin \\omega t$","$i = \\sqrt{2}\\omega Q \\cos \\omega t$","$i = \\sqrt{2}\\omega Q \\sin(\\omega t - 90^\\circ)$","$i = \\sqrt{2}\\omega Q \\cos(\\omega t - 90^\\circ)$"]'::jsonb, '2', '전류 $i$는 전하량 $Q$의 시간적 변화율입니다:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 10, '$4[\mu F]$와 $6[\mu F]$의 콘덴서를 병렬 접속하고 $10[V]$의 전압을 가했을 때 축적되는 전체 전하량 $[\mu C]$은?', '["19","50","80","100"]'::jsonb, '4', '1. 병렬 합성 정전 용량: $C = C_1 + C_2 = 4 + 6 = 10[\mu F]$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 11, '회로망 임의의 접속점에 유입되는 전류는 $\sum I = 0$이라는 법칙은?', '["쿨롱의 법칙","패러데이의 법칙","키르히호프의 제1법칙","키르히호프의 제2법칙"]'::jsonb, '3', '키르히호프의 제1법칙(전류 법칙, KCL)은 회로 접속점에서 유입전류의 총합은 유출전류의 총합과 같다는 법칙입니다.
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 12, '자체 인덕턴스가 각각 $160[mH]$, $250[mH]$인 두 코일이 있다. 두 코일 사이의 상호 인덕턴스가 $150[mH]$이면 결합 계수는?', '["55","62","75","86"]'::jsonb, '3', '결합 계수 $k$ 공식:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 13, '전기장의 세기 단위로 옳은 것은?', '["$[As/m]$","$[F/m]$","$[AT/m]$","$[V/m]$"]'::jsonb, '4', '전기장의 세기(Electric Field Strength) $E$의 단위는 $[V/m]$ 또는 $[N/C]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 14, '기전력이 $E [V]$, 내부 저항이 $r [\Omega]$인 $n$개의 전지를 직렬 연결하였다. 전체 내부 저항을 나타낸 것은?', '["$\\frac{n}{r}$","$nr$","$\\frac{r}{n}$","$nr^2$"]'::jsonb, '2', '저항 $r$개를 직렬로 연결하면 전체 저항은 합산되므로 $r + r + \dots + r = nr [\Omega]$이 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 15, '비정현파의 실효값을 나타낸 것으로 옳은 것은?', '["최대파의 실효값","각 고조파의 실효값의 합","각 고조파의 실효값 합의 제곱근","각 고조파 실효값 제곱의 합에 대한 제곱근"]'::jsonb, '4', '비정현파의 실효값(RMS)은 다음과 같이 구합니다:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 16, '평균 반지름이 $r [m]$이고, 감은 횟수가 $N$인 환상 솔레노이드에 전류 $I [A]$가 흐를 때 내부 자기장의 세기 $H [AT/m]$는?', '["$\\frac{NI}{r}$","$\\frac{NI}{2\\pi r}$","$\\frac{NI}{\\pi r}$","$\\frac{NI}{r^2}$"]'::jsonb, '2', '환상 솔레노이드 내부의 자기장 세기는 암페어의 주회적분 법칙에 의해 다음과 같습니다:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 17, '그림의 병렬 공진 회로에서 공진 주파수 $f_0 [Hz]$는? [그림 참고]', '["$\\frac{1}{2\\pi\\sqrt{LC}}$","$\\frac{1}{2\\pi LC}$","$\\frac{1}{2\\pi}\\sqrt{LC}$","$2\\pi\\sqrt{LC}$"]'::jsonb, '1', '병렬 공진 또는 직렬 공진 시의 공진 주파수 조건 $X_L = X_C$에서:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 18, '단자 1-2에서 본 노튼 등가 회로의 개방단 컨덕턴스는 몇 $[\mho]$인가? [그림 참고]', '["0.5","1","2","5.8"]'::jsonb, '3', '1. 등가 저항($R_{th}$) 계산 (전원 단락): $0.8 + (2 \parallel 3) = 0.8 + 1.2 = 2 [\Omega]$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 19, '히스테리시스손은 최대 자속 밀도 및 주파수의 각각 몇 승에 비례하는가?', '["최대 자속 밀도: 1.6, 주파수: 1.0","최대 자속 밀도: 1.0, 주파수: 1.6","최대 자속 밀도: 1.0, 주파수: 1.0","최대 자속 밀도: 1.6, 주파수: 1.6"]'::jsonb, '1', '슈타인메츠 공식에 따르면 히스테리시스손($P_h$)은 다음과 같습니다:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 20, '어떤 도체의 길이를 2배로 하고 단면적을 1/2로 했을 때의 저항은 원래 저항의 몇 배가 되는가?', '["배","배","6배","8배"]'::jsonb, '2', '저항 $R = \rho \frac{L}{A}$ 이므로:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 21, '사용 중인 변류기(CT)의 2차측을 개방하면 어떻게 되는가?', '["차 전류가 감소한다.","차 권선에 $110[V]$가 걸린다.","개방단의 전압은 불변하고 안전하다.","차 권선에 고전압이 유도된다."]'::jsonb, '4', '사용 중인 변류기의 2차측을 개방하면 1차측 부하 전류가 모두 여자 전류가 되어 철심이 포화되고, 2차 권선에 매우 높은 고전압이 유도되어 절연 파괴나 감전 사고의 위험이 있습니다. 따라서 점검 시에는 반드시 2차측을 단락시켜야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 22, '동기 전동기에 관한 내용으로 틀린 것은?', '["기동 토크가 작다.","역률을 조정할 수 없다.","난조가 발생하기 쉽다.","여자기가 필요하다."]'::jsonb, '2', '동기 전동기는 계자 전류를 조정하여 역률을 조정(진상 또는 지상)할 수 있는 것이 큰 장점입니다 (동기 조상기로 활용 가능).');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 23, '동기 전동기의 직류 여자 전류가 증가될 때의 현상으로 옳은 것은?', '["진상 역률을 만든다.","지상 역률을 만든다.","동상 역률을 만든다.","진상·지상 역률을 만든다."]'::jsonb, '1', '동기 전동기에서 과여자(계자 전류 증가)를 하면 앞선 전류가 흘러 진상 역률이 되어 콘덴서와 같은 역할을 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 24, '직류 스테핑 모터(DC stepping motor)의 특징 중 가장 옳은 것은?', '["교류 동기 서보 모터에 비하여 효율이 나쁘고 토크 발생도 작다.","입력되는 전기 신호에 따라 계속하여 회전한다.","일반적인 공작 기계에 많이 사용된다.","전기 신호를 이용하여 특수 기계의 속도, 거리, 방향 등을 정확하게 제어할 수 있다."]'::jsonb, '4', '스테핑 모터는 입력되는 각 전기 신호(펄스)에 따라 규정된 각도만큼 회전하므로 디지털 제어 장치를 통해 속도와 위치를 매우 정밀하게 제어할 수 있습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 25, '변압기유(절연유)의 구비 조건으로 옳은 것은?', '["절연 내력이 클 것","인화점이 낮을 것","응고점이 높을 것","비열이 작을 것"]'::jsonb, '1', '절연유의 구비 조건:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 26, '동기기에서 제동 권선(Damper winding)을 설치하는 이유로 옳은 것은?', '["역률 개선","출력 증가","전압 조정","난조 방지"]'::jsonb, '4', '동기 전동기에서 제동 권선은 ''난조 방지''와 ''기동 토크 발생''을 위해 설치합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 27, '낮은 전압을 높은 전압으로 승압할 때 일반적으로 사용되는 변압기의 3상 결선 방식은?', '["$\\Delta - \\Delta$","$\\Delta - Y$","$Y - Y$","$Y - \\Delta$"]'::jsonb, '2', '승압용으로는 상전압의 $\sqrt{3}$배인 선간전압을 얻을 수 있는 $\Delta - Y$ 결선이 유리하며, 강압용으로는 $Y - \Delta$ 결선이 주로 사용됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 28, '선풍기, 가정용 펌프, 헤어 드라이기 등에 주로 사용되는 전동기는?', '["단상 유도 전동기","권선형 유도 전동기","동기 전동기","직류 직권 전동기"]'::jsonb, '1', '가정용 소형 가전 제품에는 단상 유도 전동기가 가장 널리 사용됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 29, '슬립이 $4[\%]$인 유도 전동기에서 동기 속도가 $1,200[rpm]$일 때 전동기의 회전 속도 $N [rpm]$은?', '["697",",051",",152",",321"]'::jsonb, '3', '전동기 회전 속도 $N$:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 30, '3상 4극 $60[MVA]$, 역률 0.8, $60[Hz]$, $22.9[kV]$ 수차 발전기의 전부하 손실이 $1,600[kW]$이면 전부하 효율 $[\%]$은?', '["90","95","97","99"]'::jsonb, '3', '효율 $\eta = \frac{Output}{Output + Loss} \times 100$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 31, '부흐홀츠 계전기로 보호되는 기기는?', '["변압기","유도 전동기","직류 발전기","교류 발전기"]'::jsonb, '1', '부흐홀츠 계전기는 변압기 내부 고장 시 발생하는 가스나 유류의 흐름을 검출하여 동작하는 변압기 전용 기계적 보호 장치입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 32, '주상 변압기의 고압측에 여러 개의 탭을 설치하는 이유는?', '["선로 고장 대비","선로 전압 조정","선로 역률 개선","선로 과부하 방지"]'::jsonb, '2', '수전점의 전압 변동에 대응하여 변압기 2차측 전압을 적정하게 유지하기 위해 고압측 권수비를 조정하는 탭을 설치합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 33, '3상 유도 전동기에서 회전 방향을 바꾸려면 어떻게 해야 하는가?', '["전원의 극수를 바꾼다.","전원의 주파수를 바꾼다.","상 전원 3선 중 두 선의 접속을 바꾼다.","기동 보상기를 이용한다."]'::jsonb, '3', '3상 전원 중 임의의 두 선(상)의 접속을 바꾸면 회전 자계의 방향이 반대가 되어 모터가 역회전하게 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 34, '3상 전파 정류 회로에서 전원 전압이 $250[V]$일 때 부하에 나타나는 직류 전압의 최대값 $[V]$은?', '["약 177","약 292","약 337","약 530"]'::jsonb, '4', '1. 실효값 $E = 250[V]$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 35, '3단자 사이리스터가 아닌 것은?', '["SCS","SCR","TRIAC","GTO"]'::jsonb, '1', 'SCR, TRIAC, GTO는 모두 3단자 소자이지만, SCS(Silicon Controlled Switch)는 4단자 소자입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 36, '3상 농형 유도 전동기의 $Y-\Delta$ 기동 시 기동 전류를 전전압 기동 시와 비교하면 어떻게 되는가?', '["전전압 기동 전류의 1/3배로 된다.","전전압 기동 전류의 $\\sqrt{3}$배로 된다.","전전압 기동 전류의 3배로 된다.","전전압 기동 전류의 9배로 된다."]'::jsonb, '1', '$Y$ 결선으로 기동하면 전압이 $1/\sqrt{3}$이 되며, 기동 전류와 기동 토크는 모두 전전압($\Delta$) 기동 시의 $1/3$배로 줄어듭니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 37, '유도 전동기의 무부하 시 슬립($s$)은?', '["4","3","1","0"]'::jsonb, '4', '무부하 상태에서는 회전 속도 $N$이 거의 동기 속도 $N_s$와 같아지므로 슬립 $s = (N_s - N)/N_s \approx 0$ 이 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 38, '정류자와 접촉하여 전기자 권선과 외부 회로를 연결하는 역할을 하는 것은?', '["계자","전기자","브러시","계자 철심"]'::jsonb, '3', '브러시는 정류자와 미끄럼 접촉을 하며 전기자 권선에서 발생한 기전력을 외부 회로로 끌어내는 역할을 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 39, '직류 발전기의 정격 전압이 $100[V]$, 무부하 전압이 $109[V]$이다. 이 발전기의 전압 변동률 $[\%]$은?', '["1","3","6","9"]'::jsonb, '4', '전압 변동률 $\epsilon = \frac{V_0 - V_n}{V_n} \times 100$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 40, '직류 직권 전동기의 특징에 대한 설명으로 틀린 것은?', '["부하 전류가 증가하면 속도가 크게 감소한다.","기동 토크가 작다.","무부하 운전 시 위험 속도에 도달할 우려가 있다.","계자 권선과 전기자 권선이 직렬로 접속되어 있다."]'::jsonb, '2', '직류 직권 전동기는 시동 시(저속 시) 매우 큰 토크를 발생시키는 특성이 있어 전기차량이나 크레인 기동에 적합합니다. ''기동 토크가 작다''는 틀린 설명입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 41, '저압 애자 사용 공사에서 전선 상호 간의 간격은 몇 $[cm]$ 이상이어야 하는가?', '["4","5","6","8"]'::jsonb, '3', '저압 애자 사용 공사 시 이격 거리 기준:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 42, '금속 몰드의 지지점 간의 거리는 몇 $[m]$ 이하로 하는 것이 가장 바람직한가?', '["1","1.5","2","3"]'::jsonb, '2', '금속 몰드 공사 시 몰드의 지지점 간 거리는 $1.5[m]$ 이하가 되도록 하여야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 43, '합성 수지관 상호 및 관과 박스는 접속 시에 삽입하는 깊이를 관 바깥지름의 몇 배 이상으로 하여야 하는가? (단, 접착제를 사용하지 않은 경우이다.)', '["0.2","0.5","1","1.2"]'::jsonb, '4', '합성 수지관의 삽입 깊이 기준:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 44, '옥내 배선의 접속함이나 박스 내에서 접속할 때 주로 사용하는 접속법은?', '["슬리브 접속","쥐꼬리 접속","트위스트 접속","브리타니아 접속"]'::jsonb, '2', '박스 안에서 전선을 접속할 때는 주로 쥐꼬리 접속을 한 후 와이어 커넥터 등으로 절연 처리합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 45, '화약류의 분말이 전기 설비가 발화원이 되어 폭발할 우려가 있는 곳에 시설하는 저압 옥내 배선의 공사 방법으로 가장 알맞은 것은?', '["금속관 공사","애자 사용 공사","버스 덕트 공사","합성 수지 몰드 공사"]'::jsonb, '1', '폭연상 분진 또는 화약류 분말이 존재하는 장소에서는 금속관 공사 또는 케이블 공사(개장 케이블 등)가 가장 안전한 시공 방법입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 46, '위험물 등이 있는 곳에서의 저압 옥내 배선 공사 방법이 아닌 것은?', '["케이블 공사","합성 수지관 공사","금속관 공사","애자 사용 공사"]'::jsonb, '4', '가연성 위험물질이 있는 장소에서는 금속관, 합성 수지관, 케이블 공사가 허용되지만, 노출 배선인 애자 사용 공사는 위험하므로 금지됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 47, '저압 가공 전선이 철도 또는 궤도를 횡단하는 경우에는 레일면상 몇 $[m]$ 이상이어야 하는가?', '["5","5","5.5","6.5"]'::jsonb, '4', '가공 전선의 높이 기준:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 54, 'S형 슬리브를 사용하여 전선을 접속하는 경우의 유의 사항이 아닌 것은?', '["전선은 연선만 사용이 가능하다.","전선의 끝은 슬리브의 끝에서 조금 나오는 것이 좋다.","슬리브는 전선의 굵기에 적합한 것을 사용한다.","도체는 샌드페이퍼 등으로 닦아서 사용한다."]'::jsonb, '1', '슬리브 접속(S형, E형 등)은 단선과 연선 모두 사용 가능합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 55, '[한국전기설비규정(KEC)에 따른 문제 삭제]', '["-","-","-","-"]'::jsonb, '1', '현행 규정(KEC)에 맞지 않는 구 법규 문제는 제외되었습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 56, '인입용 비닐 절연 전선을 나타내는 약호는?', '["OW","EV","DV","NV"]'::jsonb, '3', 'DV(Drop Wire)는 가공 인입선용 비닐 절연 전선이며, OW는 옥외용, EV는 폴리에틸렌 절연 비닐 외장 케이블입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 57, '정격 전압 3상 $24[kV]$, 정격 차단 전류 $300[A]$인 수전 설비의 차단 용량은 몇 $[MVA]$인가?', '["7.26","8.34","47","94"]'::jsonb, '3', '3상 차단기 용량 $P_s = \sqrt{3} \times V_n \times I_s$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 1, 58, '고압 이상에서 기기의 점검·수리 시 무부하 전로를 단독으로 전로를 접속 또는 분리하는 것을 주목적으로 사용하는 기기는?', '["기중 부하 개폐기","단로기","전력 퓨즈","컷아웃 스위치"]'::jsonb, '2', '단로기(Disconnecting Switch, DS)는 소호 능력이 없으므로 부하 전류가 흐르지 않는 무부하 상태의 선로를 확실하게 분리하기 위해 사용됩니다.');
