INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 9, '정현파 교류의 평균값 $V_{av}$와 최대값 $V_m$의 관계는?', '["$V_{av} = \\frac{2}{\\pi} V_m$","$V_{av} = \\frac{\\pi}{2} V_m$","$V_{av} = \\frac{1}{\\sqrt{2}} V_m$","$V_{av} = \\sqrt{2} V_m$"]'::jsonb, '1', '정현파 교류의 평균값은 최대값의 $\frac{2}{\pi}$배($\approx 0.637$배)입니다.');
