INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 11, '물질에 따라 자석에 반발하는 물체를 무엇이라 하는가?', '["비자성체","상자성체","반자성체","강자성체"]'::jsonb, '3', '자석에 반발하는 성질(비투자율 $\mu_s < 1$)을 가진 물질을 반(역)자성체라고 합니다.');
