INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 13, '정전 용량 $C[F]$인 콘덴서에 전압 $V[V]$를 가할 때 축적되는 에너지 $W[J]$는?', '["$CV^2$","$\\frac{1}{2} CV^2$","$C^2V$","$\\frac{1}{2} C^2V$"]'::jsonb, '2', '콘덴서에 축적되는 에너지 $W$:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 14, '3상 교류 $\Delta$결선된 회로에서 선전류 $I_l$과 상전류 $I_p$의 관계는? (단, 평형 회로이다.)', '["$I_l = I_p$","$I_l = \\sqrt{3} I_p$","$I_l = 3 I_p$","$I_l = \\frac{1}{\\sqrt{3}} I_p$"]'::jsonb, '2', '$\Delta$결선에서 선전류는 상전류의 $\sqrt{3}$배이며, 위상은 $30^\circ$ 뒤집니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 15, '변압기의 기본 원리는?', '["정전기 유도 현상","자계 유도 현상","전자기 유도 현상","열전 현상"]'::jsonb, '3', '변압기는 1차 권선에 흐르는 교류 전류가 만드는 자속 변화가 2차 권선에 기전력을 유도하는 ''전자기 유도 원리''를 이용합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 16, '6극 60[Hz] 동기 전동기의 동기 속도 $N_s [rpm]$는?', '[",200",",800",",000",",600"]'::jsonb, '1', '동기 속도 $N_s = \frac{120f}{P} = \frac{120 \times 60}{6} = 1,200 [rpm]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 17, '직류 발전기에서 전기자 반작용을 방지하기 위해 주로 사용되는 권선은?', '["분권 권선","직권 권선","평복권 권선","보상 권선"]'::jsonb, '4', '전기자 반작용을 억제하기 위해 전기자 권선과 직렬로 연결하여 반대 방향의 자속을 만드는 보상 권선(Compensation winding)이 가장 효과적입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 18, '변압기에서 발생하는 손실 중 부하의 크기에 따라 변하지 않는 ''무부하손''의 대표적인 것은?', '["동손","표류 부하손","와류손","철손"]'::jsonb, '4', '철손(히스테리시스손 + 와류손)은 부하의 유무에 관계없이 일정하게 발생하는 고정손 또는 무부하손입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 19, '유도 전동기의 슬립 $s$를 나타내는 식은? (단, $N_s$: 동기 속도, $N$: 전동기 속도)', '["$s = \\frac{N_s - N}{N}$","$s = \\frac{N_s - N}{N_s}$","$s = \\frac{N}{N_s}$","$s = \\frac{N_s}{N}$"]'::jsonb, '2', '슬립 $s$는 동기 속도에 대한 속도 차의 비율입니다:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 20, '다음 중 제어 정류 소자인 SCR의 특징으로 옳은 것은? (단, 단방향과 쌍방향, 단자와 관계된 내용이다.)', '["쌍방향성 3단자 소자이다.","단방향성 3단자 소자이다.","단방향성 2단자 소자이다.","쌍방향성 2단자 소자이다."]'::jsonb, '2', 'SCR(Silicon Controlled Rectifier)은 에노드(A), 캐소드(K), 게이트(G)의 3단자를 가지며 한쪽 방향(A->K)으로만 전류를 제어하는 단방향성 소자입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 21, '유도 전동기의 속도 제어 방법 중 주파수 제어에 의한 것은?', '["인버터 제어","차 저항 제어","극수 변환","전압 제어"]'::jsonb, '1', '인버터(Inverter)는 교류의 주파수를 가변하여 유도 전동기의 속도를 제어하는 대표적인 장치입니다 ($N_s = \frac{120f}{P}$). ');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 22, '부하의 변동에 대하여 단자 전압의 변화가 가장 작은 직류 발전기는?', '["직권","분권","평복권","과복권"]'::jsonb, '3', '복권 발전기 중 전압 변동률이 거의 0에 가까워 부하 변화에도 단자 전압이 일정한 발전기는 ''평복권'' 발전기입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 23, '부하의 저항을 어느 정도 감소시켜도 전류는 일정하게 되는 수하 특성을 이용하여 정전류를 만드는 곳이나 아크 용접 등에 사용되는 직류 발전기는?', '["직권 발전기","분권 발전기","가동 복권 발전기","차동 복권 발전기"]'::jsonb, '4', '수하 특성(V-I 곡선이 급격히 떨어지는 특성)을 가진 ''차동 복권 발전기''는 일정한 전류를 유지해야 하는 아크 용접기용 발전기로 널리 쓰입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 24, '변압기유가 구비해야 할 조건 중 맞는 것은?', '["절연 내력이 작고 산화하지 않을 것","비열이 작아서 냉각 효과가 클 것","인화점이 높고 응고점이 낮을 것","절연 재료나 금속에 접촉할 때 화학 작용을 일으킬 것"]'::jsonb, '3', '변압기유의 구비 조건:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 25, '다음 단상 유도 전동기 중 기동 토크가 큰 것부터 옳게 나열한 것은?', '["반발 기동형 $\\rightarrow$ 콘덴서 기동형 $\\rightarrow$ 분상 기동형 $\\rightarrow$ 세이딩 코일형","반발 기동형 $\\rightarrow$ 분상 기동형 $\\rightarrow$ 콘덴서 기동형 $\\rightarrow$ 세이딩 코일형","콘덴서 기동형 $\\rightarrow$ 반발 기동형 $\\rightarrow$ 분상 기동형 $\\rightarrow$ 세이딩 코일형","분상 기동형 $\\rightarrow$ 콘덴서 기동형 $\\rightarrow$ 반발 기동형 $\\rightarrow$ 세이딩 코일형"]'::jsonb, '1', '단상 유도 전동기의 기동 토크 크기 순서:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 26, '유도 전동기의 제동법이 아닌 것은?', '["상 제동","발전 제동","회생 제동","역상 제동"]'::jsonb, '1', '유도 전동기의 전기적 제동법에는 역상 제동(플러깅), 발전 제동, 회생 제동이 있습니다. 3상 제동이라는 용어는 사용되지 않습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 27, '변압기, 동기기 등의 층간 단락 등의 내부 고장 보호에 사용되는 계전기는?', '["차동 계전기","접지 계전기","과전압 계전기","역상 계전기"]'::jsonb, '1', '차동 계전기(Differential Relay)는 유입 전류와 유출 전류의 차이를 이용해 기기 내부 고장을 검출하는 가장 대표적인 보호 계전기입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 28, '단상 전파 정류 회로에서 전원이 $220[V]$이면 부하에 나타나는 전압의 평균값은 약 몇 $[V]$인가?', '["99","98","57.4","97"]'::jsonb, '2', '단상 전파 정류 회로의 직류 평균 전압:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 29, 'PN 접합 정류 소자의 설명 중 틀린 것은? (단, 실리콘 정류 소자인 경우이다.)', '["온도가 높아지면 순방향 및 역방향 전류가 모두 감소한다.","순방향 전압은 P형에 (+), N형에 (-) 전압을 가함을 말한다.","정류비가 클수록 정류 특성은 좋다.","역방향 전압에서는 극히 작은 전류만이 흐른다."]'::jsonb, '1', '실리콘 반도체는 온도가 높아지면 열전도율이 좋아지고 반도체 내의 캐리어 생성이 늘어나 역방향 포화 전류가 급격히 증가합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 30, '회전자 입력 $10[kW]$, 슬립 $3[\%]$인 3상 유도 전동기의 2차 동손 $[W]$은?', '["0","0","500","700"]'::jsonb, '1', '2차 동손 $P_{c2}$ 공식:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 31, '변압기의 효율이 가장 좋을 때의 조건은?', '["철손 $=$ 동손","$철손 = \\frac{1}{2} 동손$","$동손 = \\frac{1}{2} 철손$","$동손 = 2 \\times 철손$"]'::jsonb, '1', '변압기는 고정손인 철손과 가변손인 동손이 같을 때 가장 높은 효율을 나타냅니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 32, '동기 발전기의 전기자 권선을 단절권으로 하면?', '["고조파를 제거한다.","절연이 잘 된다.","역률이 좋아진다.","기전력을 높인다."]'::jsonb, '1', '단절권은 전절권보다 기전력은 약간 줄어드나, 제5고조파 등의 고조파를 제거하여 전압의 파형을 개선하는 장점이 있습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 33, '전력 계통에 접속되어 있는 변압기나 장거리 송전 시 정전 용량으로 인한 충전 특성 등을 보상하기 위한 기기는?', '["유도 전동기","동기 발전기","유도 발전기","동기 조상기"]'::jsonb, '4', '동기 조상기(Synchronous Phase Modifier)는 계자 전류를 조정하여 앞선 전류나 뒤진 전류를 공급함으로써 계통의 전압을 조정하고 충전 특성을 보상합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 34, '전력 변환 기기가 아닌 것은?', '["변압기","정류기","유도 전동기","인버터"]'::jsonb, '3', '유도 전동기는 전기 에너지를 기계적 회전 에너지로 변환하는 동력 장치이며, 전력의 형태(전압, 전류, 주파수 등)를 변환하는 정지기는 아닙니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 35, '직류 전동기의 속도 제어법이 아닌 것은?', '["전압 제어법","계자 제어법","저항 제어법","주파수 제어법"]'::jsonb, '4', '주파수 제어법(인버터 제어)은 교류 전동기(유도 전동기)의 속도를 제어하는 방법입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 36, '변압기에서 2차측이란 무엇인가?', '["부하측","고압측","전원측","저압측"]'::jsonb, '1', '변압기에서 전원이 연결되는 쪽을 1차측, 부하가 연결되는 쪽을 2차측이라고 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 37, '동기 발전기의 병렬 운전 시 기전력의 크기가 다를 경우에 발생하는 현상은?', '["과열 현상이 나타난다.","동조 현상이 발생한다.","난조 현상이 발생한다.","무효 순환 전류가 흐른다."]'::jsonb, '4', '병렬 운전 중인 두 발전기의 기전력 크기가 다르면 기전력의 차에 의해 두 발전기 사이에 ''무효 순환 전류(무효 횡류)''가 흐르게 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 38, '8극 파권 직류 발전기의 전기자 권선의 병렬 회로수 $a$는 얼마로 하고 있는가?', '["","","6","8"]'::jsonb, '2', '직류기에서 파권(Wave winding)의 병렬 회로수는 극수에 관계없이 항상 2개($a=2$)입니다. (Answer index 1 corresponds to option 2)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 39, '변압기의 절연 내력 시험법이 아닌 것은?', '["유도 시험","가압 시험","단락 시험","충격 전압 시험"]'::jsonb, '3', '절연 내력 시험에는 가압 시험, 유도 시험, 충격 전압 시험 등이 있으며, 단락 시험은 임피던스 전압이나 동손을 측정하기 위한 시험입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 40, '동기 전동기 중 안정도 증진법으로 틀린 것은?', '["전기자 저항 감소","관성 효과 증대","동기 임피던스 증대","속응 여자 채용"]'::jsonb, '3', '안정도를 높이려면 동기 임피던스(리액턴스)를 작게 해야 하며, 관성 모멘트를 키우고 속응 여자 방식을 채택해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 41, '금속관을 구부릴 때 굴곡 반지름은 관 안지름의 몇 배 이상이어야 하는가?', '["6","8","10","12"]'::jsonb, '1', '금속관 공사에서 관을 굽힐 때 굴곡 반지름은 관 안지름의 6배 이상이 되도록 규정되어 있습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 42, '금속관 배관 공사를 할 때 금속관을 구부리는 데 사용하는 공구는?', '["히키(hickey)","파이프 렌치(pipe wrench)","오스터(oster)","파이프 커터(pipe cutter)"]'::jsonb, '1', '금속관의 굴곡 작업(굽힘)에는 히키(Hickey) 또는 벤더(Bender)를 사용합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 43, '접지 저항값에 가장 큰 영향을 주는 것은?', '["접지선 굵기","접지 전극 크기","온도","대지 저항"]'::jsonb, '4', '접지 저항은 대지의 고유 저항(성질)에 가장 큰 영향을 받으며, 이는 토양의 종류, 수분 함량 등에 따라 달라집니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 44, '접지선을 철주, 기타 금속체를 따라 시설하는 경우 접지극은 지중에서 그 금속체로부터 몇 $[cm]$ 이상 떼어 매설해야 하는가?', '["30","60","75","100"]'::jsonb, '4', '접지극을 철주 등의 금속체로부터 이격하여 매설할 때는 상호 간섭 방지를 위해 지중에서 $1[m]$($100[cm]$) 이상 이격해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 45, '금속관 공사에서 녹아웃의 지름이 금속관의 지름보다 큰 경우에 사용하는 재료는?', '["로크 너트","부싱","링 리듀서","새들"]'::jsonb, '3', '박스의 녹아웃(구멍)이 금속관보다 클 경우, 크기를 맞추기 위해 끼워 넣는 보조 재료를 링 리듀서(Ring Reducer)라고 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 46, '애자 사용 공사 시 사용할 수 없는 전선은?', '["고무 절연 전선","폴리에틸렌 절연 전선","플루오르 수지 절연 전선","인입용 비닐 절연 전선"]'::jsonb, '4', '애자 사용 공사 시에는 절연 전선을 사용해야 하나, 인입용 비닐 절연 전선(DV)과 옥외용 비닐 절연 전선(OW)은 사용할 수 없습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 47, '전선의 재료로서 구비해야 할 조건이 아닌 것은?', '["기계적 강도가 클 것","가요성이 풍부할 것","고유 저항이 클 것","비중이 작을 것"]'::jsonb, '3', '전선은 전류를 잘 흘려야 하므로 전기 저항(고유 저항)이 작아야 하며, 전도율은 높아야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 48, '[한국전기설비규정(KEC)에 따른 문제 삭제]', '["-","-","-","-"]'::jsonb, '1', '현행 법령(KEC)에 맞지 않는 구 법규 문제는 제외되었습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 49, '화재 시 소방대가 조명 기구나 파괴용 기구 등 소화 활동에 필요한 전원으로 사용하기 위해 설치하는 기구는?', '["비상등","유도등","비상 콘센트","누전 경보기"]'::jsonb, '3', '비상 콘센트는 화재 시 소방대원이 소화 활동에 필요한 전원을 확보하기 위해 설치하는 설비입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 50, '가공 전선 지지물의 기초 강도는 주체에 가하여지는 하중에 대하여 안전율을 얼마 이상으로 하여야 하는가? (단, 이상 시 상정하중 이외인 경우이다.)', '["1.0","1.5","1.8","2.0"]'::jsonb, '4', '가공 전선 지지물의 기초 안전율은 일반적으로 2.0 이상으로 하여야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 51, '전주 외등 설치 시 조명 기구를 전주에 부착하는 경우 부착한 점으로부터 돌출되는 수평 거리는 몇 $[m]$ 이내로 하여야 하는가?', '["0.5","0.8","1.0","1.2"]'::jsonb, '3', '전주 외등 시설 시 조명 기구의 수평 돌출 거리는 $1.0[m]$ 이내로 제한됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 52, '전선의 접속에 대한 설명으로 틀린 것은?', '["접속 부분의 전기 저항을 20[\\%] 이상 증가되도록 한다.","접속 부분의 인장 강도를 80[\\%] 이상 유지되도록 한다.","접속 부분에 전선 접속 기구를 사용한다.","알루미늄 전선과 구리선의 접속 시 전기적 부식이 생기지 않도록 한다."]'::jsonb, '1', '전선을 접속할 때는 접속 부분의 전기 저항이 증가하지 않도록 시공해야 합니다. ''20% 이상 증가''는 틀린 설명입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 53, '간선에 접속하는 전동기의 정격 전류의 합계가 $50[A]$를 초과하는 경우에는 그 정격 전류 합계의 몇 배에 견디는 전선을 선정하여야 하는가?', '["8","","5",""]'::jsonb, '2', '간선 허용 전류 선정 기준:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 54, '전선 약호가 VV인 케이블의 종류로 옳은 것은?', '["6/1[kV] 비닐 절연 비닐시스 케이블","6/1[kV] EP 고무 절연 클로로프렌시스 케이블","6/1[kV] EP 고무 절연 비닐시스 케이블","6/1[kV] 비닐 절연 비닐 캡타이어 케이블"]'::jsonb, '1', 'VV 케이블은 Vinyl insulated Vinyl sheathed cable의 약자로, 0.6/1[kV] 비닐 절연 비닐 시스 케이블을 의미합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 55, '저압 2조의 전선 설치 시 크로스 완금의 표준 길이 $[mm]$는?', '["900",",400",",800",",400"]'::jsonb, '1', '저압 가공 전선로에서 2조의 전선을 설치할 때 사용하는 크로스 완금의 표준 길이는 $900[mm]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 56, '다음 중 전등 1개를 2개소에서 점멸하고자 할 때 3로 스위치가 필요한 개수는 얼마인가?', '["개","개","개","개"]'::jsonb, '3', '2개소 점멸 회로를 구성하기 위해서는 양쪽 끝에 3로 스위치가 각각 1개씩, 총 2개가 필요합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 57, '수·변전 설비 구성 기기의 계기용 변압기(PT) 설명으로 맞는 것은?', '["높은 전압을 낮은 전압으로 변성하는 기기이다.","높은 전류를 낮은 전류로 변성하는 기기이다.","회로에 병렬로 접속하여 사용하는 기기이다.","부족 전압 트립 코일의 전원으로 사용된다."]'::jsonb, '1', 'PT(Potential Transformer)는 고전압을 전압계나 계전기가 사용할 수 있는 낮은 전압($110[V]$ 등)으로 변성하는 기기입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 58, '폭연상 분진이 존재하는 곳의 저압 옥내 배선 공사 시 공사 방법으로 짝지어진 것은?', '["금속관 공사, MI 케이블 공사, 개장된 케이블 공사","CD 케이블 공사, MI 케이블 공사, 금속관 공사","CD 케이블 공사, 비닐 절연 전선, 제1종 캡타이어 케이블 공사","제1종 캡타이어 케이블 공사, 합성 수지관 공사"]'::jsonb, '1', '폭발성 분진이 있는 위험 장소에서는 가장 견고하고 기밀성이 좋은 금속관 공사 또는 특수 케이블 공사(MI 등)가 사용되어야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 59, '일반적으로 가공 전선로의 지지물에 시설하는 지선(Stay)의 안전율은 얼마 이상인가?', '["1","1.5","2.2","2.5"]'::jsonb, '4', '가공 전선로 지지의 강도를 보강하는 지선(Stay)의 안전율은 2.5 이상이어야 합니다. (단 구리선 등은 1.5)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 2, 60, '$22.9[kV-Y]$ 가공 전선의 굵기는 단면적이 몇 $[mm^2]$ 이상이어야 하는가? (단, 동선의 경우이다.)', '["","","","50"]'::jsonb, '2', '$22.9[kV]$ 다중 접지 가공 전선로의 전선 굵기는 단면적 $32[mm^2]$ 이상의 나동선 또는 이와 동등 이상의 강도와 굵기를 가져야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 0, 1, 0, 'There is no ''2015년 제3회 기출문제'' (2015, Round 03) in the provided document. Please check the round number or provide the correct document.', '[]'::jsonb, '1', '');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 0, 1, 0, 'The requested Year: 2015, Round: 03 is not found in the provided document. The available rounds for 2015 are 1, 2, 4, and 5.', '[]'::jsonb, '1', '');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 1, '콘덴서의 정전 용량에 대한 설명으로 틀린 것은?', '["전압에 반비례한다.","이동 전하량에 비례한다.","극판의 넓이에 비례한다.","극판의 간격에 비례한다."]'::jsonb, '4', '정전 용량 $C = \epsilon \frac{A}{d}$에서 정전 용량은 유전율($\epsilon$)과 극판의 넓이($A$)에 비례하고, 극판의 간격($d$)에 반비례합니다. 전압과는 관계가 없습니다. 따라서 ''극판의 간격에 비례한다''는 설명은 틀린 것입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 2, '정전 에너지 $W[J]$를 구하는 식으로 옳은 것은? (단, $C$는 콘덴서 용량$[\mu F]$, $V$는 공급 전압 $q[V]$이다.)', '["$W = \\frac{1}{2} CV^2$","$W = \\frac{1}{2} CV$","$W = \\frac{1}{2} C^2 V$","$W = 2CV^2$"]'::jsonb, '1', '콘덴서(도체)에 축적되는 정전 에너지는 $W = \frac{1}{2} QV = \frac{1}{2} CV^2 = \frac{Q^2}{2C} [J]$ 로 정의됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 3, '등전위면과 전기력선의 교차 관계는?', '["직각으로 교차한다.","°로 교차한다.","5°로 교차한다.","교차하지 않는다."]'::jsonb, '1', '등전위면과 전기력선은 서로 수직(직각)으로 교차하는 특성이 있습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 4, '전기 분해를 통하여 석출되는 물질의 양은 통과한 전기량 및 화학당량과 어떤 관계가 있는가?', '["전기량과 화학당량에 비례한다.","전기량과 화학당량에 반비례한다.","전기량에 비례하고 화학당량에 반비례한다.","전기량에 반비례하고 화학당량에 비례한다."]'::jsonb, '1', '패러데이의 전기 분해 법칙에 따라, 전극에서 석출되는 물질의 양($W$)은 통과한 전기량($Q = It$)에 비례하고 화학당량($k$)에도 비례합니다. ($W = kQ = kIt$)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 5, '평형 3상 교류 회로에서 $Y$결선할 때 선간 전압 $V_l$과 상전압 $V_p$와의 관계는?', '["$V_l = V_p$","$V_l = \\sqrt{2} V_p$","$V_l = \\sqrt{3} V_p$","$V_l = \\frac{1}{\\sqrt{3}} V_p$"]'::jsonb, '3', '$Y$결선(성형 결선)에서 선간 전압은 상전압의 $\sqrt{3}$배이며, 위상은 상전압보다 $30^\circ$ 앞섭니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 6, '2전력계법으로 3상 전력을 측정할 때 지시값이 $P_1 = 200[W]$, $P_2 = 200[W]$일 때 부하 전력$[W]$은?', '["0","0","600","800"]'::jsonb, '2', '2전력계법에서 전체 유효 전력 $P = P_1 + P_2$ 입니다. 따라서 $200 + 200 = 400[W]$가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 7, '20분간 876,000[J]의 일을 할 때 전력$[kW]$은?', '["73","7.3","73","730"]'::jsonb, '1', '전력 $P = \frac{W}{t}$입니다. 시간($t$)을 초 단위로 환산하면 $20 \times 60 = 1,200$초이므로, $P = \frac{876,000}{1,200} = 730[W] = 0.73[kW]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 8, '전류에 의해 만들어지는 자기장의 자기력선 방향을 간단하게 알아내는 방법은?', '["플레밍의 왼손 법칙","렌츠의 자기 유도 법칙","앙페르의 오른 나사 법칙","패러데이의 전자 유도 법칙"]'::jsonb, '3', '앙페르의 오른 나사 법칙은 전류의 방향을 오른 나사의 진행 방향으로 할 때, 자기장의 방향이 나사의 회전 방향과 일치한다는 법칙입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 9, '$R = 5[\Omega]$, $L = 30[mH]$인 $R-L$ 직렬 회로에 $V = 200[V]$, $f = 60[Hz]$인 교류 전압을 가할 때 전류의 크기는 약 몇 $[A]$인가?', '["8.67","42","6.17","25"]'::jsonb, '3', '유도성 리액턴스 $X_L = 2\pi fL = 2\pi \times 60 \times 30 \times 10^{-3} \approx 11.31[\Omega]$입니다. 합성 임피던스 $Z = \sqrt{R^2 + X_L^2} = \sqrt{5^2 + 11.31^2} \approx 12.37[\Omega]$이므로, 전류 $I = \frac{V}{Z} = \frac{200}{12.37} \approx 16.17[A]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 10, '1[cm]당 권수가 10인 무한 길이 솔레노이드에 1[A]의 전류가 흐르고 있을 때 솔레노이드 외부 자계의 세기$[AT/m]$는?', '["","5","",""]'::jsonb, '1', '이상적인 솔레노이드(무한 길이)에서 내부는 평등 자계가 형성되지만, 외부 자계의 세기는 0입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 11, '그림과 같은 $R-L$ 병렬 회로에서 $R = 25[\Omega]$, $\omega L = \frac{100}{3}[\Omega]$일 때, 200[V]의 전압을 가하면 코일에 흐르는 전류 $I_L[A]$은? [그림 참고]', '["","8","6.0","8.2"]'::jsonb, '3', '병렬 회로에서 각 소자에 걸리는 전압은 동일합니다. 코일에 흐르는 전류 $I_L = \frac{V}{X_L} = \frac{200}{100/3} = 200 \times \frac{3}{100} = 6[A]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 12, '다음 중 1[V]와 같은 값을 갖는 것은?', '["[J/C]","[Wb/m]","[\\Omega/m]","[A \\cdot sec]"]'::jsonb, '1', '전위(전압)의 정의는 단위 전하당 한 일의 양이므로, $V = \frac{W}{Q} [J/C]$ 가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 13, '다음 그림과 같은 회로의 저항값이 $R_1 > R_2 > R_3 > R_4$일 때, 전류가 최소로 흐르는 저항은? [그림 참고]', '["$R_1$","$R_2$","$R_3$","$R_4$"]'::jsonb, '1', '병렬 접속된 저항 회로에서 각 저항에 흐르는 전류는 저항값에 반비례합니다($I = V/R$). 따라서 저항값이 가장 큰 $R_1$에 가장 적은 전류가 흐릅니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 14, '원자핵의 구속력을 벗어나서 물질 내에서 자유로이 이동할 수 있는 것은?', '["중성자","양자","분자","자유 전자"]'::jsonb, '4', '자유 전자는 원자핵의 구속력을 벗어나 물질 내에서 자유롭게 이동하며 전기를 전달하는 역할을 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 15, '권수가 150인 코일에서 2초간 1[Wb]의 자속이 변화한다면, 코일에 발생하는 유도 기전력의 크기는 몇 [V]인가?', '["50","75","0","50"]'::jsonb, '2', '패러데이의 전자 유도 법칙에 의해 $e = |-N \frac{d\phi}{dt}| = 150 \times \frac{1}{2} = 75[V]$가 유도됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 16, '복소수에 대한 설명으로 틀린 것은?', '["실수부와 허수부로 구성된다.","허수를 제곱하면 음수가 된다.","복소수는 $A = a + jb$의 형태로 표시된다.","거리와 방향을 나타내는 스칼라량으로 표시한다."]'::jsonb, '4', '복소수는 크기(거리)와 방향을 모두 갖는 벡터량(또는 복소평면상의 점)을 나타내는 데 사용됩니다. 단순히 크기만 나타내는 스칼라량과는 다릅니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 17, '자기 인덕턴스가 각각 $L_1[H]$, $L_2[H]$인 두 개의 코일이 직렬로 가동 접속되었을 때, 합성 인덕턴스는? (단, 자기력선에 의한 영향을 서로 받는 경우이다.)', '["$L_1 + L_2 - M$","$L_1 + L_2 - 2M$","$L_1 + L_2 + M$","$L_1 + L_2 + 2M$"]'::jsonb, '4', '두 코일이 자속이 합쳐지는 방향(가동 접속)으로 직렬 연결되면 합성 인덕턴스는 $L = L_1 + L_2 + 2M$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 18, '저항이 있는 도선에 전류가 흐르면 열이 발생한다. 이와 같이 전류의 열작용과 가장 관계가 깊은 법칙은?', '["패러데이의 법칙","키르히호프의 법칙","줄의 법칙","옴의 법칙"]'::jsonb, '3', '줄의 법칙은 저항에 전류가 흐를 때 발생하는 열량($H$)이 전류의 제곱과 저항, 시간에 비례한다는 법칙입니다. ($H = 0.24 I^2 Rt$)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 19, '$R-L$ 직렬 회로에 교류 전압 $v = V_m \sin \omega t [V]$를 가했을 때 회로의 위상차 $\theta$를 나타낸 것은?', '["$\\theta = \\tan^{-1} \\frac{R}{\\omega L}$","$\\theta = \\tan^{-1} \\frac{\\omega L}{R}$","$\\theta = \\tan^{-1} \\frac{1}{R\\omega L}$","$\\theta = \\tan^{-1} \\frac{R}{\\sqrt{R^2 + (\\omega L)^2}}$"]'::jsonb, '2', '$R-L$ 직렬 회로의 위상각 $\theta$는 임피던스의 허수부($\omega L$)를 실수부($R$)로 나눈 값의 아크탄젠트로 구합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 20, '그림에서 a-b 간의 합성 저항은 c-d 간의 합성 저항의 몇 배인가? [그림 참고]', '["배","배","배","배"]'::jsonb, '2', 'a-b 합성 저항은 평형 브리지 회로로 보아 $r$이고, c-d 합성 저항은 $2r, r, 2r$의 병렬 접속으로 $r/2$입니다. 따라서 $r$은 $r/2$의 2배가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 21, '변압기의 임피던스 전압이란?', '["정격 전류가 흐를 때의 변압기 내의 전압 강하","여자 전류가 흐를 때의 2차측 단자 전압","정격 전류가 흐를 때의 2차측 단자 전압","차 단락 전류가 흐를 때 변압기 내의 전압 강하"]'::jsonb, '1', '임피던스 전압은 변압기에 정격 전류가 흐를 때 내부 임피던스에 의해 발생하는 전압 강하를 의미합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 22, '그림은 전력 제어 소자를 이용한 위상 제어 회로이다. 전동기의 속도를 제어하기 위하여 ''가'' 부분에 사용되는 소자는? [그림 참고]', '["전력용 트랜지스터","제너 다이오드","트라이액","레굴레이터 78XX 시리즈"]'::jsonb, '3', '그림은 DIAC과 TRIAC을 이용한 교류 위상 제어 회로입니다. ''가''에 해당하는 소자는 양방향 제어가 가능한 트라이액(TRIAC)입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 23, '정격이 10,000[V], 500[A], 역률 90[%]의 3상 동기 발전기의 단락 전류 $I_s[A]$는? (단, 단락비는 1.3으로 하고 전기자 저항은 무시한다.)', '["50","550","650","750"]'::jsonb, '3', '단락 전류 $I_s = K \times I_n$ (단락비 $\times$ 정격 전류) 입니다. 따라서 $1.3 \times 500 = 650[A]$가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 24, '2대의 동기 발전기 A, B가 병렬 운전하고 있을 때 여자 전류를 증가시키면 어떻게 되는가?', '["A기의 역률은 낮아지고 B기의 역률은 높아진다.","A기의 역률은 높아지고 B기의 역률은 낮아진다.","A, B 양 발전기의 역률이 높아진다.","A, B 양 발전기의 역률이 낮아진다."]'::jsonb, '1', '동기 발전기 병렬 운전 중 한 쪽(A기)의 여자 전류를 증가시키면 그 기기의 역률은 지상으로 기울어 낮아지고, 상대 기기(B기)의 역률은 진상으로 기울어 높아지게 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 25, '다음의 정류 곡선 중 브러시의 후단에서 불꽃이 발생하기 쉬운 곳은?', '["직선 정류","정현파 정류","과정류","부족 정류"]'::jsonb, '4', '정류 곡선 종류별 특징:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 26, '슬립이 일정한 경우 유도 전동기의 공급 전압이 $\frac{1}{2}$로 감소하면 토크는 처음에 비해 어떻게 되는가?', '["배가 된다.","배가 된다.","$\\frac{1}{2}$로 줄어든다.","$\\frac{1}{4}$로 줄어든다."]'::jsonb, '4', '유도 전동기의 토크($T$)는 공급 전압의 제곱($V^2$)에 비례합니다. 전압이 $1/2$배가 되면 토크는 $(1/2)^2 = 1/4$배로 감소합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 27, '권선형에서 비례 추이를 이용한 기동법은?', '["리액터 기동법","기동 보상기법","차 저항 기동법","Y-\\Delta 기동법"]'::jsonb, '3', '권선형 유도 전동기는 2차 회로에 가변 저항을 연결하여 슬립과 토크의 비례 관계(비례 추이)를 이용해 기동 토크를 크게 만드는 2차 저항 기동법을 사용합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 28, '동기 발전기의 역률각이 90° 늦을 때의 전기자 반작용은?', '["증자 작용","편자 작용","교차 작용","감자 작용"]'::jsonb, '4', '동기 발전기에서 전류의 위상이 전압보다 $90^\circ$ 늦을 때(L부하)는 주자속을 감소시키는 감자 작용이 일어납니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 29, '유도 전동기가 회전하고 있을 때 생기는 손실 중에서 구리손이란?', '["브러시의 마찰손","베어링의 마찰손","표유 부하손","차, 2차 권선의 저항손"]'::jsonb, '4', '구리손(동손)은 권선의 전기 저항에 의해 발생하는 열손실($I^2 R$)을 의미합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 30, '그림에서와 같이 $\text{\textcircled{\small{가}}}$, $\text{\textcircled{\small{나}}}$의 양 자극 사이에 정류자를 가진 코일을 두고 $\text{\textcircled{\small{다}}}$, $\text{\textcircled{\small{라}}}$에 직류를 공급하여 $X, X''$를 축으로 하여 코일을 시계 방향으로 회전시키고자 한다. $\text{\textcircled{\small{가}}}$, $\text{\textcircled{\small{나}}}$의 자극 극성과 $\text{\textcircled{\small{다}}}$, $\text{\textcircled{\small{라}}}$의 전원 극성을 어떻게 해야 되는가? [그림 참고]', '["$\\text{\\textcircled{\\small{가}}}$ N, $\\text{\\textcircled{\\small{나}}}$ S, $\\text{\\textcircled{\\small{다}}}$ +, $\\text{\\textcircled{\\small{라}}}$ -","$\\text{\\textcircled{\\small{가}}}$ N, $\\text{\\textcircled{\\small{나}}}$ S, $\\text{\\textcircled{\\small{다}}}$ -, $\\text{\\textcircled{\\small{라}}}$ +","$\\text{\\textcircled{\\small{가}}}$ S, $\\text{\\textcircled{\\small{나}}}$ N, $\\text{\\textcircled{\\small{다}}}$ +, $\\text{\\textcircled{\\small{라}}}$ -","$\\text{\\textcircled{\\small{가}}}$ S, $\\text{\\textcircled{\\small{나}}}$ N, $\\text{\\textcircled{\\small{다}}}$ -, $\\text{\\textcircled{\\small{라}}}$ +"]'::jsonb, '2', '플레밍의 왼손 법칙(전동기 원리)을 적용하여 시계 방향 회전력을 얻기 위한 극성 조합을 찾으면 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 31, '그림과 같은 분상 기동형 단상 유도 전동기를 역회전시키기 위한 방법이 아닌 것은? [그림 참고]', '["원심력 스위치를 개로 또는 폐로한다.","기동 권선이나 운전 권선의 어느 한 권선의 단자 접속을 반대로 한다.","기동 권선의 단자 접속을 반대로 한다.","운전 권선의 단자 접속을 반대로 한다."]'::jsonb, '1', '단상 유도 전동기를 역회전시키려면 주권선(운전 권선) 또는 보조권선(기동 권선)의 극성(단자 접속)을 반대로 해야 합니다. 원심력 스위치는 기동이 끝난 후 보조권선을 분리하는 역할만 하므로 회전 방향과는 무관합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 32, '다음 그림은 단상 변압기 결선도이다. 1, 2차는 각각 어떤 결선인가? [그림 참고]', '["$Y-Y$ 결선","$\\Delta-Y$ 결선","$\\Delta-\\Delta$ 결선","$Y-\\Delta$ 결선"]'::jsonb, '4', '그림에서 1차측(입력)은 중성점이 있는 $Y$결선이고, 2차측(출력)은 고리 모양의 $\Delta$결선임을 확인할 수 있습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 33, '다음 그림의 직류 전동기는 어떤 전동기인가? [그림 참고]', '["직권 전동기","타여자 전동기","분권 전동기","복권 전동기"]'::jsonb, '3', '계자 권선($F$)과 전기자($A$)가 서로 병렬로 연결되어 전원을 공급받는 형태는 분권 전동기입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 34, '전력용 변압기의 내부 고장 보호용 계전 방식은?', '["역상 계전기","차동 계전기","접지 계전기","과전류 계전기"]'::jsonb, '2', '변압기 내부 고장 시 1차측과 2차측의 전류 차이를 검출하여 동작하는 비율 차동 계전기(또는 차동 계전기)가 주로 사용됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 35, '다음 중 병렬 운전 시 균압선을 설치해야 하는 직류 발전기는?', '["분권","차동 복권","평복권","부족 복권"]'::jsonb, '3', '직권 계자가 포함된 직권 발전기나 복권 발전기(과복권, 평복권)는 병렬 운전 시 안정한 운전을 위해 각 발전기의 전압을 일정하게 유지해주는 균압선이 필요합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 36, '다음 변압기 극성에 관한 설명 중 틀린 것은?', '["우리나라는 감극성이 표준이다.","차와 2차 권선에 유기되는 전압의 극성이 반대이며 감극성이다.","상 결선 시 극성을 고려한다.","병렬 운전 시 극성을 고려해야 한다."]'::jsonb, '2', '감극성(subtractive polarity)은 1차 권선과 2차 권선에 유도되는 기전력의 방향이 같은 것을 의미합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 37, '애벌런치 항복 전압은 온도 증가에 따라 어떻게 변화하는가?', '["감소한다.","증가한다.","증가했다 감소한다.","무관하다."]'::jsonb, '2', '애벌런치(Avalanche) 항복 전압은 온도 계수가 양(+)이므로 온도가 상승하면 항복 전압도 함께 증가합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 38, '용량이 작은 유도 전동기의 경우 전부하에서의 슬립[%]은?', '["~2.5","5~4","5~10","~20"]'::jsonb, '3', '소형 유도 전동기는 대형에 비해 손실률이 커서 전부하 슬립이 대략 $5 \sim 10 [\%]$ 정도로 비교적 큽니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 39, '60[Hz], 20,000[kVA]의 발전기의 회전수가 1,200[rpm]이라면 이 발전기의 극수는 얼마인가?', '["6","8","",""]'::jsonb, '1', '동기 속도 $N_s = \frac{120f}{P}$ 식에서 $P = \frac{120f}{N_s} = \frac{120 \times 60}{1,200} = 6$극이 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 40, '변압기를 $Y-\Delta$로 연결할 때 1, 2차 간의 위상차는?', '["5도","도","5도","60도"]'::jsonb, '2', '$Y-\Delta$ 결선이나 $\Delta-Y$ 결선은 1차측과 2차측 사이에 $30^\circ$의 위상차가 발생합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 41, '저압 연접 인입선의 시설 규정으로 적합한 것은?', '["분기점으로부터 100[m] 이내에 시설","6[m] 도로를 횡단하여 시설","수용가 옥내를 관통하여 설치","지름 1.5[mm] 인입용 비닐 절연 전선을 사용"]'::jsonb, '1', '저압 연접 인입선은 분기점으로부터 100[m]를 넘지 않는 지역에 시설해야 합니다. 또한 전폭 5[m]를 넘는 도로를 횡단하지 않아야 하며, 옥내를 관통하지 않아야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 42, '사람이 쉽게 접촉하는 장소에 설치하는 누전 차단기의 사용 전압 기준은 몇 [V] 초과인가?', '["50","0","50","0"]'::jsonb, '1', '사용 전압이 50[V]를 초과하는 저압의 기계 기구로서 사람이 쉽게 접촉할 우려가 있는 장소에 시설하는 것에는 누전 차단기를 설치해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 43, '전선을 접속할 경우의 설명으로 틀린 것은?', '["접속 부분의 전기 저항이 증가되지 않아야 한다.","전선의 세기를 80[%] 이상 감소시키지 않아야 한다.","접속 부분은 접속 기구를 사용하거나 납땜을 하여야 한다.","알루미늄 전선과 동선을 접속하는 경우 전기적 부식이 생기지 않도록 해야 한다."]'::jsonb, '2', '전선을 접속할 때 전선의 인장 강도(세기)를 20[%] 이상 감소시키지 않아야 합니다. 즉, 원래 세기의 80[%] 이상을 유지해야 합니다. 따라서 ''80% 이상 감소시키지 않아야 한다''는 틀린 설명입니다(20% 이상 감소시키지 않아야 함).');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 44, '[한국전기설비규정(KEC)에 따른 삭제]', '["삭제된 문항입니다.","삭제된 문항입니다.","삭제된 문항입니다.","삭제된 문항입니다."]'::jsonb, '1', '이 문항은 KEC 규정 변경으로 인해 삭제되었습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 45, '화약류 저장소에서 백열전등이나 형광등 또는 이들에 전기를 공급하기 위한 전기 설비를 시설하는 경우 전로의 대지 전압[V]은?', '["0[V] 이하","0[V] 이하","0[V] 이하","0[V] 이하"]'::jsonb, '4', '화약류 저장소의 전기 설비에서 대지 전압은 300[V] 이하로 제한됩니다. 또한 배선은 케이블 또는 금속관 공사를 사용해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 46, '연피 없는 케이블을 배선할 때 직각 구부리기(L형)는 대략 굴곡 반지름을 케이블 바깥지름의 몇 배 이상으로 하는가?', '["","","6",""]'::jsonb, '3', '연피가 없는 케이블의 굴곡 반지름은 케이블 외경의 6배 이상으로 해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 47, '정격 전류 20[A]인 전동기 1대와 정격 전류 5[A]인 전열기 3대가 연결된 분기 회로에 시설하는 과전류 차단기의 정격 전류는?', '["5","50","75","0"]'::jsonb, '3', '전동기 부하가 포함된 분기 회로의 과전류 차단기 정격 전류($I_B$)는 일반적으로 $3 \times I_m + I_h$로 계산합니다. $3 \times 20 + (5 \times 3) = 60 + 15 = 75[A]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 48, '접지 저항 측정 방법으로 가장 적당한 것은?', '["절연 저항계","전력계","교류의 전압, 전류계","콜라우슈 브리지"]'::jsonb, '4', '접지 저항 측정에는 콜라우슈 브리지(Kohlrausch bridge)법이나 어스테스터(접지저항계)가 사용됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 49, '큰 건물의 공사에서 콘크리트에 구멍을 뚫어 드라이브 핀을 경제적으로 고정하는 공구는?', '["스패너","드라이브 이트 툴","오스터","녹아웃 펀치"]'::jsonb, '2', '드라이브 이트 툴(Drive-it tool)은 화약의 폭발력을 이용하여 콘크리트나 강재에 드라이브 핀을 박아 넣는 공구입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 50, '전자 접촉기 2대를 이용하여 유도 전동기 1대를 정·역 운전하고 있는 시설에서 전자 접촉기 2대가 동시에 여자되어 상간 단락되는 것을 방지하기 위하여 구성하는 회로는?', '["자기 유지 회로","순차 제어 회로","Y-\\Delta 기동 회로","인터로크 회로"]'::jsonb, '4', '인터로크(Interlock) 회로는 두 개의 기기가 동시에 동작하지 못하도록 구속하는 회로로, 정·역회전 시 상간 단락 사고를 방지하기 위해 필수적입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 51, '다음 중 버스 덕트가 아닌 것은?', '["플로어 버스 덕트","피더 버스 덕트","트로리 버스 덕트","플러그인 버스 덕트"]'::jsonb, '1', '버스 덕트의 종류에는 피더 버스 덕트, 익스팬션 버스 덕트, 탭핑 버스 덕트, 트로리 버스 덕트, 플러그인 버스 덕트 등이 있습니다. 플로어 덕트는 별도의 금속 덕트 공사 방식입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 52, '가공 전선로의 지지물에서 다른 지지물을 거치지 아니하고 수용 장소의 인입선 접속점에 이르는 가공 전선을 무엇이라 하는가?', '["연접 인입선","가공 인입선","구내 전선로","구내 인입선"]'::jsonb, '2', '가공 전선로의 지지물에서 직접 수용 장소에 이르는 가공 전선은 ''가공 인입선''입니다. 한 수용가에서 다른 수용가로 분기하여 도달하는 선은 ''연접 인입선''입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 53, '합성수지관 공사의 설명 중 틀린 것은?', '["관의 지지점 간의 거리는 1.5[m] 이하로 할 것","합성수지관 안에서는 전선의 접속점이 없도록 할 것","전선은 절연 전선(옥외용 비닐 절연 전선을 제외한다)일 것","관 상호 간 및 박스와는 관을 삽입하는 깊이를 관의 바깥지름의 1.5배 이상으로 할 것"]'::jsonb, '4', '합성수지관 상호 접속 시 삽입 깊이는 관 외경의 1.2배(접착제 사용 시 0.8배) 이상이어야 합니다. 따라서 ''1.5배 이상으로 할 것''이라는 수치는 틀린 기준입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 54, '배선 설계를 위한 전등 및 소형 전기 기계 기구의 부하 용량 산정 시 건축물의 종류에 대응한 표준 부하를 20[$VA/m^2$]으로 적용하는 건축물은?', '["교회, 극장","호텔, 병원","은행, 상점","아파트, 미용원"]'::jsonb, '2', '건축물별 표준 부하[$VA/m^2$]:
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 55, '지중 전선로를 직접 매설식에 의하여 시설하는 경우 차량, 기타 중량물의 압력을 받을 우려가 있는 장소의 매설 깊이[m]는?', '["6[m] 이상","[m] 이상","5[m] 이상","[m] 이상"]'::jsonb, '2', '직접 매설식에서 차량 등 중량물의 압력을 받을 우려가 있는 장소는 1.0[m] 이상, 기타 장소는 0.6[m] 이상의 깊이로 매설해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 56, '동전선의 직선 접속에서 단선 및 연선에 적용되는 접속 방법은?', '["직선 맞대기용 슬리브에 의한 압착 접속","가는 단선(2.6[mm] 이상)의 분기 접속","S형 슬리브에 의한 분기 접속","터미널 러그에 의한 접속"]'::jsonb, '1', '동전선의 직선 접속에는 주로 직선 맞대기용 슬리브를 이용한 압착 접속 방식이 사용됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 4, 57, '전기 난방 기구인 전기 담요나 전기 장판의 보호용으로 사용되는 퓨즈는?', '["플러그 퓨즈","온도 퓨즈","절연 퓨즈","유리관 퓨즈"]'::jsonb, '2', '전기 담요, 전기 장판과 같은 발열 기구에는 비정상적인 온도 상승을 감지하여 전로를 차단하는 온도 퓨즈가 사용됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 1, '자체 인덕턴스가 40[mH]인 코일에 10[A]의 전류가 흐를 때 저장되는 에너지는 몇 [J]인가?', '["","","","8"]'::jsonb, '1', '코일에 축적되는 에너지 $W = \frac{1}{2} LI^2$입니다. $W = \frac{1}{2} \times 40 \times 10^{-3} \times 10^2 = 2[J]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 2, '다음 중 큰 값일수록 좋은 것은?', '["접지 저항","절연 저항","도체 저항","접촉 저항"]'::jsonb, '2', '절연 저항은 전류가 새지 않도록 차단하는 저항이므로 값이 클수록 안전하고 좋습니다. 접지 저항, 도체 저항, 접촉 저항은 작을수록 좋습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 3, '$L_1, L_2$ 두 코일이 접속되어 있을 때 누설 자속이 없는 이상적인 코일 간의 상호 인덕턴스는?', '["$M = \\sqrt{L_1 + L_2}$","$M = \\sqrt{L_1 - L_2}$","$M = \\sqrt{L_1 L_2}$","$M = \\frac{L_1}{L_2}$"]'::jsonb, '3', '상호 인덕턴스 $M = k\sqrt{L_1 L_2}$에서 누설 자속이 없는 이상적인 상태(결합 계수 $k = 1$)이므로 $M = \sqrt{L_1 L_2}$가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 4, '3[kW] 전열기를 정격 상태에서 20분간 사용하였을 때 열량은 몇 [kcal]인가?', '["0","520","610","860"]'::jsonb, '4', '열량 $H = 0.24 Pt [cal]$ 식에서 전기 열량 환산 계수 $1[kWh] = 860[kcal]$를 이용하면 $H = 860 \times P[kW] \times t[hour] = 860 \times 3 \times \frac{20}{60} = 860[kcal]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 5, '대칭 3상 $\Delta$결선에서 선전류와 상전류와의 위상 관계는?', '["상전류가 $\\frac{\\pi}{3}[rad]$ 앞선다.","상전류가 $\\frac{\\pi}{3}[rad]$ 뒤진다.","상전류가 $\\frac{\\pi}{6}[rad]$ 앞선다.","상전류가 $\\frac{\\pi}{6}[rad]$ 뒤진다."]'::jsonb, '3', '$\Delta$결선(델타 결선)에서 선전류는 상전류보다 크기는 $\sqrt{3}$배 크고 위상은 $30^\circ (\pi/6[rad])$ 뒤집니다. 역으로 상전류가 선전류보다 $30^\circ$ 앞서게 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 6, '10[\Omega]의 저항과 $R[\Omega]$의 저항이 병렬로 접속되고 10[\Omega]의 전류가 5[A], $R[\Omega]$의 저항의 전류가 2[A]라면 저항 $R[\Omega]$은?', '["","","5",""]'::jsonb, '3', '병렬 회로에서 전압은 동일하므로 $V = 10 \times 5 = 50[V]$입니다. 따라서 $R = V / I = 50 / 2 = 25[\Omega]$가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 7, '저항 8[\Omega]과 코일이 직렬로 접속된 회로에 200[V]의 교류 전압을 가하면 20[A]의 전류가 흐른다. 코일의 리액턴스는 몇 [\Omega]인가?', '["","","6","8"]'::jsonb, '3', '전체 임피던스 $Z = V/I = 200/20 = 10[\Omega]$입니다. $Z^2 = R^2 + X_L^2$에서 $X_L = \sqrt{10^2 - 8^2} = 6[\Omega]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 8, '가정용 전등 전압이 200[V]이다. 이 교류의 최댓값은 몇 [V]인가?', '["70.7","86.7","4","82.8"]'::jsonb, '4', '교류의 최댓값 $V_m = \sqrt{2} \times V_{rms}$ (실효값) 입니다. $V_m = 1.414 \times 200 \approx 282.8[V]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 9, '다음 설명 중 틀린 것은?', '["리액턴스는 주파수의 함수이다.","콘덴서는 직렬로 연결할수록 용량이 커진다.","저항은 병렬로 연결할수록 저항치가 작아진다.","코일은 직렬로 연결할수록 인덕턴스가 커진다."]'::jsonb, '2', '콘덴서(커패시터)를 직렬로 연결하면 전체 정전 용량은 작아집니다 ($1/C = 1/C_1 + 1/C_2$). 콘덴서는 병렬로 연결해야 용량이 커집니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 10, '쿨롱의 법칙에서 2개의 점전하 사이에 작용하는 정전력의 크기는?', '["두 전하의 곱에 비례하고 거리에 반비례한다.","두 전하의 곱에 반비례하고 거리에 비례한다.","두 전하의 곱에 비례하고 거리의 제곱에 비례한다.","두 전하의 곱에 비례하고 거리의 제곱에 반비례한다."]'::jsonb, '4', '쿨롱의 법칙 $F = k \frac{Q_1 Q_2}{r^2}$에 의해 정전력은 두 전하의 곱에 비례하고 거리의 제곱에 반비례합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 11, '$m_1 = 4 \times 10^{-5} [Wb]$, $m_2 = 6 \times 10^{-3} [Wb]$, $r = 10[cm]$이면 두 자극 $m_1, m_2$ 사이에 작용하는 힘은 약 몇 [N]인가?', '["52","","","52"]'::jsonb, '1', '자기력 $F = 6.33 \times 10^4 \times \frac{m_1 m_2}{r^2} [N]$ 입니다. 거리는 미터 단위($0.1[m]$)로 환산하면 $F = 6.33 \times 10^4 \times \frac{4 \times 10^{-5} \times 6 \times 10^{-3}}{0.1^2} \approx 1.52[N]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 12, '$i = 8 + j6[A]$로 표시되는 전류의 크기 $I[A]$는 얼마인가?', '["6","8","",""]'::jsonb, '3', '복소수 전류의 크기(절대값) $|I| = \sqrt{Re^2 + Im^2} = \sqrt{8^2 + 6^2} = 10[A]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 13, '$R = 6[\Omega]$, $X_c = 8[\Omega]$일 때 임피던스 $\dot{Z} = 6 - j8[\Omega]$으로 표시되는 것은 일반적으로 어떤 회로인가?', '["RC 직렬 회로","RL 직렬 회로","RC 병렬 회로","RL 병렬 회로"]'::jsonb, '1', '임피던스의 허수부가 마이너스인 것은 용량성 리액턴스가 포함된 회로이며, 실수부와 허수부의 단순 합으로 표기된 것은 직렬 회로를 의미합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 14, '$R-L-C$ 병렬 공진 회로에서 공진 주파수는?', '["$\\frac{1}{\\pi \\sqrt{LC}}$","$\\frac{1}{\\sqrt{LC}}$","$\\frac{2\\pi}{\\sqrt{LC}}$","$\\frac{1}{2\\pi \\sqrt{LC}}$"]'::jsonb, '4', '공진 조건인 $X_L = X_C$를 만족하는 주파수는 직렬/병렬에 관계없이 $f = \frac{1}{2\pi \sqrt{LC}} [Hz]$ 가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 15, '비유전율이 큰 산화티탄 등을 유전체로 사용한 것으로 극성이 없으며 가격에 비해 성능이 우수하여 널리 사용되고 있는 콘덴서의 종류는?', '["전해 콘덴서","세라믹 콘덴서","마일러 콘덴서","마이카 콘덴서"]'::jsonb, '2', '세라믹 콘덴서는 유전 상수가 매우 큰 티탄산 바륨 등을 사용하며, 소형화가 가능하고 극성이 없어 교류 회로 등에 널리 쓰입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 16, '전기 분해를 하면 석출되는 물질의 양은 통과한 전기량에 관계가 있다. 이것을 나타낸 법칙은?', '["옴의 법칙","쿨롱의 법칙","앙페르의 법칙","패러데이의 법칙"]'::jsonb, '4', '패러데이의 전기 분해 법칙은 전극에서 석출되는 물질의 양이 통과한 총 전기량에 비례한다는 법칙입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 17, '$Y$결선의 전원에서 각 상전압이 100[V]일 때 선간 전압은 약 몇 [V]인가?', '["0","50","73","95"]'::jsonb, '3', '$Y$결선에서 선간 전압 $V_l = \sqrt{3} V_p$입니다. $100 \times 1.732 \approx 173[V]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 18, '"전류의 방향과 자장의 방향은 각각 나사의 진행 방향과 회전 방향에 일치한다."와 관계가 있는 법칙은?', '["플레밍의 왼손 법칙","앙페르의 오른 나사 법칙","플레밍의 오른손 법칙","키르히호프의 법칙"]'::jsonb, '2', '앙페르의 오른 나사 법칙은 전류에 의해 형성되는 자기장의 방향을 정의하는 법칙입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 19, '삼각파 전압의 최댓값이 $V_m$ [V]일 때 실효값은?', '["$V_m$","$\\frac{V_m}{\\sqrt{2}}$","$\\frac{2 V_m}{\\pi}$","$\\frac{V_m}{\\sqrt{3}}$"]'::jsonb, '4', '삼각파 또는 톱니파의 실효값($V_{rms}$)은 최댓값($V_m$)의 $1/\sqrt{3}$배입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 20, '$i(t) = I_m \sin \omega t [A]$인 사인파 교류에서 $\omega t$가 몇 도일 때 순시값과 실효값이 같게 되는가?', '["°","5°","60°","90°"]'::jsonb, '2', '정현파의 실효값 $I = \frac{I_m}{\sqrt{2}}$입니다. 순시값 $I_m \sin \omega t = \frac{I_m}{\sqrt{2}}$ 가 되려면 $\sin \omega t = \frac{1}{\sqrt{2}}$ 즉, $\omega t = 45^\circ$ 이어야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 21, '100[V], 10[A], 전기자 저항 1[\Omega], 회전수 1,800[rpm]인 전동기의 역기전력은 몇 [V]인가?', '["90","0","0","86"]'::jsonb, '1', '전동기의 역기전력 $E = V - I_a R_a$ 입니다. $E = 100 - (10 \times 1) = 90[V]$가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 22, '입력으로 펄스 신호를 가해 주고 속도를 입력 펄스의 주파수에 의해 조절하는 전동기는?', '["전기 동력계","서보 전동기","스테핑 전동기","권선형 유도 전동기"]'::jsonb, '3', '스테핑 전동기(Stepping Motor)는 디지털 펄스 신호에 따라 일정한 각도씩 회전하며, 펄수 수로 위치를, 펄스 주파수로 속도를 제어합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 23, '농형 유도 전동기의 기동법이 아닌 것은?', '["차 저항기법","Y-\\Delta 기동법","전전압 기동법","기동 보상기에 의한 기동법"]'::jsonb, '1', '2차 저항 기동법은 회전자에 권선이 감겨 있는 ''권선형 유도 전동기''에서 사용되는 기동법입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 24, '동기 전동기의 장점이 아닌 것은?', '["직류 여자가 필요하다.","전부하 효율이 양호하다.","역률 1로 운전할 수 있다.","동기 속도를 얻을 수 있다."]'::jsonb, '1', '별도의 직류 전원(여자 장치)이 필요한 것은 동기 전동기의 특징이자 구조적 복잡함을 초래하는 단점에 해당합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 25, '정격 속도로 운전하는 무부하 분권 발전기의 계자 저항이 60[\Omega], 계자 전류가 1[A], 전기자 저항이 0.5[\Omega]이라 하면 유도 기전력은 약 몇 [V]인가?', '["5","50.5","60.5","80.5"]'::jsonb, '3', '단자 전압 $V = I_f R_f = 1 \times 60 = 60[V]$입니다. 발전기의 유도 기전력 $E = V + I_a R_a$ 에서 무부하시 $I_a = I + I_f = 0 + 1 = 1[A]$이므로, $E = 60 + (1 \times 0.5) = 60.5[V]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 26, '고압 전동기 철심의 강판 홈(slot)의 모양은?', '["반폐형","개방형","반구형","밀폐형"]'::jsonb, '2', '고압 기기의 경우 코일의 절연 내력을 높이기 위해 제작이 용이한 개방형 스롯을 주로 사용합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 27, '직류 발전기의 전기자 반작용의 영향에 대한 설명으로 틀린 것은?', '["브러시 사이의 불꽃을 발생시킨다.","주자속이 찌그러지거나 감소된다.","전기자 전류에 의한 자속이 주자속에 영향을 준다.","회전 방향과 반대 방향으로 자기적 중성축이 이동된다."]'::jsonb, '4', '직류 발전기에서 전기자 반작용에 의한 자기적 중성축의 이동 방향은 ''회전 방향''입니다. (전동기는 회전 반대 방향)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 28, '다음 제동 방법 중 급정지하는 데 가장 좋은 제동 방법은?', '["발전 제동","회생 제동","역상 제동","단상 제동"]'::jsonb, '3', '역상 제동(Plugging)은 전동기의 상 순서를 바꾸어 반대 방향의 토크를 발생시켜 급격히 정지시키는 방법으로, 제동력이 매우 큽니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 29, '변압기의 2차측을 개방하였을 경우 1차측에 흐르는 전류는 무엇에 의하여 결정되는가?', '["저항","임피던스","누설 리액턴스","여자 어드미턴스"]'::jsonb, '4', '2차측을 개방한 무부하 상태에서 1차측에 흐르는 전류는 여자 전류이며, 이는 변압기의 여자 어드미턴스($Y_0$)에 의해 결정됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 30, '다음 직류 분권 전동기에서 운전 중 계자 권선의 저항을 증가하면 회전 속도의 값은?', '["감소한다.","증가한다.","일정하다.","관계없다."]'::jsonb, '2', '회전 속도 $N \propto (V - I_a R_a) / \phi$ 식에서 계자 저항이 증가하면 계자 전류가 감소하여 자속($\phi$)이 줄어듭니다. 분모인 자속이 줄어드므로 속도는 증가하게 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 31, '다음 그림은 직류 발전기의 분류 중 어느 것에 해당되는가? [그림 참고]', '["분권 발전기","직권 발전기","자석 발전기","복권 발전기"]'::jsonb, '4', '그림은 전기자와 직렬인 직권 계자 권선($F_s$)과 병렬인 분권 계자 권선($F$)을 모두 갖추고 있는 복권 발전기의 회로도입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 32, '변압기에 대한 설명 중 틀린 것은?', '["전압을 변성한다.","전력을 발생하지 않는다.","정격 출력은 1차측 단자를 기준으로 한다.","변압기의 정격 용량은 피상 전력으로 표시한다."]'::jsonb, '3', '변압기의 정격 출력(용량)은 2차측 단자에서 공급할 수 있는 부하 용량을 기준으로 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 33, '유도 전동기가 많이 사용되는 이유가 아닌 것은?', '["값이 저렴","취급이 어려움","전원을 쉽게 얻음","구조가 간단하고 튼튼함"]'::jsonb, '2', '유도 전동기는 구조가 간단하여 취급 및 유지보수가 매우 용이한 것이 가장 큰 장점 중 하나입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 34, '변압기의 V결선의 특징으로 틀린 것은?', '["고장시 응급 처치 방법으로도 쓰인다.","단상 변압기 2대로 3상 전력을 공급한다.","부하 증가가 예상되는 지역에 시설한다.","V결선 시 출력은 \\Delta 결선 시 출력과 그 크기가 같다."]'::jsonb, '4', '$V$결선 출력은 $\sqrt{3} P_1$ 이고, 원래의 $\Delta$결선 출력은 $3 P_1$ 이므로 용량이 $1/\sqrt{3} \approx 57.7\%$ 로 줄어듭니다. 따라서 크기가 같다는 설명은 틀린 것입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 35, '3상 유도 전동기의 2차 저항을 2배로 하면 그 값이 2배로 되는 것은?', '["슬립","토크","전류","역률"]'::jsonb, '1', '비례 추이 원리에 의해 최대 토크와 정격 토크를 발생하는 슬립($s$)은 2차 저항($R_2$)에 비례하여 변합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 36, '반도체 사이리스터에 의한 전동기의 속도 제어 중 주파수 제어는?', '["초퍼 제어","인버터 제어","컨버터 제어","브리지 정류 제어"]'::jsonb, '2', '인버터(Inverter)는 직류를 교류로 변환하면서 전압과 주파수를 동시에 조절(VVVF)하여 전동기의 속도를 광범위하게 제어합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 37, '슬립 $s = 5[\%]$, 저항 $r_2 = 0.1[\Omega]$인 유도 전동기의 등가 저항 $R[\Omega]$은 얼마인가?', '["","5","9",""]'::jsonb, '3', '유도 전동기의 등가 저항 $R = \frac{1-s}{s} r_2$ 입니다. $R = \frac{1-0.05}{0.05} \times 0.1 = 19 \times 0.1 = 1.9[\Omega]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 38, '동기 발전기의 병렬 운전 중 주파수가 틀리면 어떤 현상이 나타나는가?', '["무효 전력이 생긴다.","무효 순환 전류가 흐른다.","유효 순환 전류가 흐른다.","출력이 요동치고 권선이 가열된다."]'::jsonb, '4', '동기기 병렬 운전 시 주파수가 다르면 유효 순환 전류가 흘러서 출력이 요동치게 되고 기계적 진동과 함께 열이 발생합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 39, '부흐홀쓰 계전기의 설치 위치는?', '["콘서베이터 내부","변압기 주탱크 내부","변압기의 고압측 부싱","변압기 본체와 콘서베이터 사이"]'::jsonb, '4', '부흐홀쓰 계전기는 변압기 내부 고장 시 발생하는 가스와 유류를 검출하기 위해 본체와 콘서베이터를 연결하는 배관 도중에 설치합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 40, '변압기의 용도가 아닌 것은?', '["교류 전압의 변환","주파수의 변환","임피던스의 변환","교류 전류의 변환"]'::jsonb, '2', '변압기는 전자 유도 작용을 이용해 전압과 전류를 변환하지만, 주파수는 변환할 수 없습니다. 주파수 변환은 컨버터/인버터 등을 통해 수행해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 41, '가로 20[m], 세로 18[m], 천장 높이 3.85[m], 작업면 높이 0.85[m], 간접 조명 방식인 호텔 연회장의 실지수는 약 얼마인가?', '["6","6","6","6"]'::jsonb, '3', '작업면 상 천장 높이 $h = 3.85 - 0.85 = 3[m]$입니다. 실지수 $RI = \frac{XY}{h(X+Y)} = \frac{20 \times 18}{3 \times (20 + 18)} \approx 3.16$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 42, '주상 변압기 1차측 보호 장치로 사용하는 것은?', '["컷 아웃 스위치","자동 구분 개폐기","캐치 홀더","리클로저"]'::jsonb, '1', '주상 변압기 1차측(고압측)에는 과전류 차단 및 개폐를 위해 컷 아웃 스위치(COS)를 설치합니다. 2차측에는 캐치 홀더를 사용합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 43, '화약류 저장 장소의 배선 공사에서 전용 개폐기에서 화약류 저장소의 인입구까지는 어떤 공사를 하여야 하는가?', '["케이블을 사용한 옥측 전선로","금속관을 사용한 지중 전선로","케이블을 사용한 지중 전선로","금속관을 사용한 옥측 전선로"]'::jsonb, '3', '화약류 저장소의 인입구까지의 배선은 케이블을 사용하여 반드시 지중에 시설해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 44, '굵은 전선이나 케이블을 절단할 때 사용되는 공구는?', '["클리퍼","펜치","나이프","플라이어"]'::jsonb, '1', '클리퍼(Clipper)는 손으로 절단하기 힘든 굵은 전선이나 볼트 등을 절단할 때 사용하는 공구입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 45, '물탱크의 물의 양에 따라 동작하는 자동 스위치는?', '["부동 스위치","압력 스위치","타임 스위치","로 스위치"]'::jsonb, '1', '부동 스위치(Float switch)는 수면의 높이에 따라 떠오르는 부자(Float)를 이용해 접점을 개폐하는 장치입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 46, 'ACSR 약호의 품명은?', '["경동 연선","중공 연선","알루미늄선","강심 알루미늄 연선"]'::jsonb, '4', 'ACSR(Aluminum Cable Steel Reinforced)은 강심 알루미늄 연선을 의미하며, 인장 강도가 커서 가공 송전 선로에 널리 쓰입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 47, '후강 전선관의 관 호칭은 ( ㉠ ) 크기로 정하여 ( ㉡ )로 표시하는데 ㉠, ㉡에 들어갈 내용으로 옳은 것은?', '["㉠ 안지름, ㉡ 홀수","㉠ 안지름, ㉡ 짝수","㉠ 바깥지름, ㉡ 홀수","㉠ 바깥지름, ㉡ 짝수"]'::jsonb, '2', '후강 전선관은 내경(안지름)을 기준으로 하며, 16, 22, 28 등 짝수로 호칭을 표시합니다. (박강 전선관은 외경 기준 홀수 표시)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 48, '배전반 및 분전반의 설치 장소로 적합하지 않은 곳은?', '["안정된 장소","밀폐된 장소","개폐기를 쉽게 개폐할 수 있는 장소","전기 회로를 쉽게 조작할 수 있는 장소"]'::jsonb, '2', '배전반 및 분전반은 점검 및 조작이 쉬운 개방된 장소에 설치해야 하며, 밀폐되거나 은폐된 장소는 피해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 49, '소매분, 전분, 기타 가연성의 분진이 존재하는 곳의 저압 옥내 배선 공사 방법에 해당되는 것으로 짝지어진 것은?', '["케이블 공사, 애자 사용 공사","금속관 공사, 콤바인 덕트관","케이블 공사, 금속관 공사, 애자 사용 공사","케이블 공사, 금속관 공사, 합성 수지관 공사"]'::jsonb, '4', '가연성 분진이 있는 장소의 옥내 배선은 합성수지관, 금속관, 케이블 공사를 사용할 수 있습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 50, '합성 수지관 배선에서 경질 비닐 전선관의 굵기에 해당되지 않는 것은? (단, 관의 호칭을 말한다.)', '["","6","8",""]'::jsonb, '3', '경질 비닐 전선관(VE)의 표준 규격은 14, 16, 22, 28, 36... 등이며 18은 규격에 없습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 51, '전선의 도체 단면적이 2.5[$mm^2$]인 전선 3본을 동일 관 내에 넣는 경우의 2종 가요 전선관의 최소 굵기[mm]는?', '["","5","7",""]'::jsonb, '2', '규정된 수용 표에 따라 단면적 $2.5[mm^2]$ 전선 3본을 넣을 수 있는 2종 가요 전선관의 최소 호칭은 15호입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 52, '전로에 지락이 생겼을 경우에 부하 기기, 금속제 외함 등에 발생하는 고장 전압 또는 지락 전류를 검출하는 부분과 차단기 부분을 조합하여 자동적으로 전로를 차단하는 장치는?', '["누전 차단 장치","과전류 차단기","누전 경보 장치","배선용 차단기"]'::jsonb, '1', '누전 차단기(ELB)는 지락 전류를 검출하여 전로를 자동 차단함으로써 감전 및 화재 사고를 방지하는 장치입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 53, '연피 케이블을 직접 매설식에 의하여 차량, 기타 중량물의 압력을 받을 우려가 있는 장소에 시설하는 경우 매설 깊이는 몇 [m] 이상이어야 하는가?', '["6","","","6"]'::jsonb, '2', '직접 매설식 지중 전선로에서 차량 등 중량물 압력 우려 장소는 1.0[m] 이상(기타 0.6[m] 이상)의 깊이로 매설해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 54, '[한국전기설비규정(KEC)에 따른 삭제]', '["삭제된 문항입니다.","삭제된 문항입니다.","삭제된 문항입니다.","삭제된 문항입니다."]'::jsonb, '1', '이 문항은 KEC 규정 변경으로 인해 삭제되었습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 55, '전주를 건주할 경우에 A종 철근 콘크리트 주의 길이가 10[m]이면 땅에 묻는 표준 깊이는 최저 약 몇 [m]인가? (단, 설계 하중이 6.8[kN] 이하이다.)', '["5","","7",""]'::jsonb, '3', '설계 하중 $6.8[kN]$ 이하인 지지물의 매설 깊이는 전체 길이의 $1/6$ 이상입니다. $10 \times 1/6 \approx 1.67$ 이므로 표준 깊이는 $1.7[m]$ 가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 56, '노출 장소 또는 점검 가능한 은폐 장소에서 제2종 가요 전선관을 시설하고 제거하는 것이 부자유하거나 점검 불가능한 경우의 곡률 반지름은 안지름의 몇 배 이상으로 하여야 하는가?', '["","","5","6"]'::jsonb, '4', '가요 전선관의 굴곡 반지름은 안지름의 6배 이상(점검 가능 장소에서 시설 및 제거 용이 시 3배)으로 해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 57, '일반적으로 정크션 박스 내에서 사용되는 전선 접속 방식은?', '["슬리브","코드 넛트","코드 파스너","와이어 커넥터"]'::jsonb, '4', '박스 내에서 전선을 꼬아 접속할 때 절연과 기계적 강도를 위해 와이어 커넥터를 주로 사용합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 58, '저압 옥내 간선으로부터 분기하는 곳에 설치하여야 하는 것은?', '["과전압 차단기","과전류 차단기","누전 차단기","지락 차단기"]'::jsonb, '2', '간선에서 분기하여 부하에 이르는 전로에는 과부하 및 단락 보호를 위해 과전류 차단기를 설치해야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 59, '하나의 콘센트에 둘 또는 세 가지의 기계 기구를 끼워서 사용할 때 사용되는 것은?', '["노출형 콘센트","키리스 소켓","멀티 탭","아이언 플러그"]'::jsonb, '3', '하나의 콘센트에 여러 기기를 연결하여 사용하는 이동식 분기 장치를 멀티 탭이라고 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2015, 5, 60, '저·고압 가공 전선이 철도 또는 궤도를 횡단하는 경우 높이는 궤조면상 몇 [m] 이상이어야 하는가?', '["","8.5","7.5","6.5"]'::jsonb, '4', '가공 전선로가 철도 또는 궤도를 횡단하는 경우 표준 높이는 궤조면(레일면) 상 $6.5[m]$ 이상입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 1, '동일한 저항 4개를 접속하여 얻을 수 있는 최대 저항값은 최소 저항값의 몇 배인가?', '["","","","6"]'::jsonb, '3', '· 최대 저항값: 직렬 $R_{직} = 4R [\Omega]$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 2, '$200[V]$, $2[kW]$의 전열선 2개를 같은 전압에서 직렬로 접속한 경우의 전력은 병렬로 접속한 경우의 전력보다 어떻게 되는가?', '["$\\frac{1}{2}$로 줄어든다.","$\\frac{1}{4}$로 줄어든다.","배로 증가한다.","배로 증가한다."]'::jsonb, '1', '1. 저항 1개의 저항 $R = V^2 / P = 200^2 / 2000 = 20[\Omega]$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 3, '권수 300회의 코일에 $6[A]$의 전류가 흘러서 $0.05[Wb]$의 자속이 코일을 지난다고 하면, 이 코일의 자체 인덕턴스는 몇 $[H]$인가?', '["5","5","5","5"]'::jsonb, '2', '인덕턴스 공식 $L = \frac{N\Phi}{I}$를 이용합니다.
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 4, '황산구리($CuSO_4$) 전해액에 2개의 구리판을 넣고 전원을 연결하였을 때 음극에서 나타나는 현상으로 옳은 것은?', '["변화가 없다.","구리판이 두터워진다.","구리판이 얇아진다.","수소 가스가 발생한다."]'::jsonb, '1', '전기분해 시 음극(-)에서는 금속 이온이 전자를 얻어 금속으로 석출되므로 구리판이 두터워집니다. 양극(+)에서는 구리가 녹아 나와 얇아집니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 5, '그림과 같은 회로에서 저항 $R_1$에 흐르는 전류는? [그림 참고]', '["$\\frac{I \\cdot R_1}{R_1 + R_2}$","$\\frac{I \\cdot R_2}{R_1 + R_2}$","$\\frac{V \\cdot R_1}{R_1 + R_2}$","$\\frac{V \\cdot R_2}{R_1 + R_2}$"]'::jsonb, '1', '병렬 회로에서의 전류 분배 법칙에 의해
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 6, '변위전류밀도와 관계 없는 것은?', '["전계의 세기","유전율","자계의 세기","전속밀도"]'::jsonb, '3', '변위전류밀도 $J_d$는 전속밀도의 시간적 변화율로 정의됩니다. $J_d = \frac{\partial D}{\partial t} = \epsilon \frac{\partial E}{\partial t}$ 이므로 전속밀도($D$), 전계의 세기($E$), 유전율($\epsilon$)과는 직접적인 관계가 있으나 자계의 세기($H$)와는 관계가 없습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 7, '벡터 $\vec{A} = 5e^{-r} \cos \phi \vec{a_r} - 5 \cos \phi \vec{a_z}$ 가 원통좌표계로 주어졌다. 점 $(2, \frac{3\pi}{2}, 0)$ 에서의 $\nabla \times \vec{A}$를 구하였을 때 $\vec{a_z}$ 방향의 성분(계수)은?', '["5","-2.5","","-0.34"]'::jsonb, '4', '원통좌표계에서 회전($\nabla \times \vec{A}$)의 $\vec{a_z}$ 성분은 $(\nabla \times \vec{A})_z = \frac{1}{r} [ \frac{\partial (r A_\phi)}{\partial r} - \frac{\partial A_r}{\partial \phi} ]$ 입니다. 주어진 벡터에서 $A_\phi = 0$ 이고 $A_r = 5e^{-r} \cos \phi$ 이므로, $(\nabla \times \vec{A})_z = \frac{1}{r} [ 0 - \frac{\partial}{\partial \phi}(5e^{-r} \cos \phi) ] = \frac{5e^{-r} \sin \phi}{r}$ 입니다. 점 $(2, \frac{3\pi}{2}, 0)$을 대입하면 $r=2, \phi=\frac{3 \pi}{2}$ 이므로 $\frac{5e^{-2} \sin(\frac{3\pi}{2})}{2} = \frac{5 \times 0.1353 \times (-1)}{2} \approx -0.34$ 가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 8, '대지면 높이 $h[m]$로 평행하게 가설된 매우 긴 선전하(선전하 밀도 $\lambda[C/m]$)가 지면으로부터 받는 힘 $[N/m]$은 어떤 관계를 가지는가?', '["$h$에 비례한다","$h$에 반비례한다","$h^2$에 비례한다","$h^2$에 반비례한다"]'::jsonb, '2', '영상전하법에 의해 대지면 아래 $-h$ 지점에 반대 부호의 영상전하 $-\lambda$가 있다고 가정하면, 두 선전하 사이의 거리는 $2h$가 됩니다. 이때 단위 길이당 작용하는 힘 $F = \frac{\lambda^2}{4\pi \epsilon_0 h}$ 이므로 높이 $h$에 반비례하게 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 9, '비투자율 800, 원형단면적 $10 cm^2$, 평균자로의 길이 $30 cm$인 환상철심에 600회의 권선을 감은 코일이 있다. 여기에 $1 A$의 전류가 흐를 때 코일 내에 생기는 자속은 약 몇 $[Wb]$인가?', '["$1 \\times 10^{-3}$","$1 \\times 10^{-4}$","$2 \\times 10^{-3}$","$2 \\times 10^{-4}$"]'::jsonb, '3', '자속 $\Phi = \frac{NI}{R_m} = \frac{\mu N I A}{l} = \frac{\mu_0 \mu_r N I A}{l}$ 공식을 사용합니다. $\Phi = \frac{4\pi \times 10^{-7} \times 800 \times 600 \times 1 \times 10 \times 10^{-4}}{0.3} \approx 2 \times 10^{-3} [Wb]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 10, '내부저항이 $r[\Omega]$인 전지 $M$개를 병렬로 연결했을 때, 전지로부터 최대전력을 공급받기 위한 부하저항 $[\Omega]$은?', '["$r/M$","$Mr$","$r$","$M^2 r$"]'::jsonb, '1', '최대전력 전달 조건은 부하저항($R$)이 전원의 내부 합성저항과 같을 때 성립합니다. 저항 $r$인 전지 $M$개가 병렬로 연결되어 있으므로 내부 합성저항은 $r/M$이 되며, 따라서 부하저항도 $r/M$일 때 최대전력이 공급됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 11, '서로 멀리 떨어져 있는 두 도체를 각각 $V_1, V_2 [V] (V_1 > V_2)$의 전위로 충전한 후 가느다란 도선으로 연결하였을 때 그 도선에 흐르는 전하 $Q[C]$는? (단, $C_1, C_2$는 두 도체의 정전용량이다.)', '["$\\frac{C_1 C_2 (V_1 - V_2)}{C_1 + C_2}$","$\\frac{2 C_1 C_2 (V_1 - V_2)}{C_1 + C_2}$","$\\frac{C_1 C_2 (V_1 - V_2)}{2(C_1 + C_2)}$","$\\frac{2(C_1 V_1 - C_2 V_2)}{C_1 C_2}$"]'::jsonb, '1', '두 도선을 연결하면 전위가 같아지며, 이때의 공통 전위 $V = \frac{C_1 V_1 + C_2 V_2}{C_1 + C_2}$가 됩니다. 이동한 전하량 $Q = C_1(V_1 - V)$를 계산하면 $\frac{C_1 C_2 (V_1 - V_2)}{C_1 + C_2}$를 얻을 수 있습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 12, '자속밀도가 $10 [Wb/m^2]$인 자계 내에 길이 $4 [cm]$의 도체를 자계와 직각으로 놓고 이 도체를 0.4초 동안 $1 [m]$씩 균일하게 이동하였을 때 발생하는 기전력은 몇 $[V]$인가?', '["","","",""]'::jsonb, '1', '유기기전력 $e = Blv$ 공식을 적용합니다. 속도 $v = 1/0.4 = 2.5 [m/s]$이므로, $e = 10 \times 0.04 \times 2.5 = 1 [V]$ 가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 13, '반지름이 $3m$인 구에 공간전하밀도가 $1 C/m^3$가 분포되어 있을 경우 구의 중심으로부터 $1m$인 곳의 전계의 세기는 몇 $[V/m]$인가?', '["$\\frac{1}{2\\epsilon_0}$","$\\frac{1}{3\\epsilon_0}$","$\\frac{1}{4\\epsilon_0}$","$\\frac{1}{6\\epsilon_0}$"]'::jsonb, '2', '가우스 법칙에 의해 전하가 균일하게 분포된 구 내부($r \le a$)에서의 전계 $E = \frac{\rho r}{3\epsilon_0}$ 입니다. $\rho=1, r=1$을 대입하면 $E = \frac{1}{3\epsilon_0}$ 이 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 14, '한 변의 길이가 $3 [m]$인 정삼각형의 회로에 $2 [A]$의 전류가 흐를 때 정삼각형 중심에서의 자계의 크기 $H$는 몇 $[AT/m]$인가?', '["$1/\\pi$","$2/\\pi$","$3/\\pi$","$9/\\pi$"]'::jsonb, '3', '한 변이 $a$인 정삼각형 중심의 자계 세기 공식 $H = \frac{9I}{2\pi a}$를 사용합니다. $a=3, I=2$를 대입하면 $H = \frac{9 \times 2}{2\pi \times 3} = \frac{3}{\pi} [AT/m]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 15, '전선을 균일하게 2배의 길이로 당겨 늘였을 때 전선의 체적이 불변이라면 저항은 몇 배가 되는가?', '["배","배","배","배"]'::jsonb, '3', '저항 $R = \rho \frac{l}{A}$에서 체적 $V = Al$이 일정하므로, 길이가 2배($2l$)가 되면 단면적은 1/2배($A/2$)가 됩니다. 따라서 새로운 저항 $R'' = \rho \frac{2l}{A/2} = 4R$이 되어 4배가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 16, '반지름 $a[m]$인 구대칭 전하에 의한 구 내외의 전계의 세기 그래프로 옳은 것은?', '["내부에서 $r$에 비례하고 외부에서 $1/r^2$에 비례하는 그래프","내부에서 일정하고 외부에서 $1/r$에 비례하는 그래프","내부에서 0이고 외부에서 $1/r^2$에 비례하는 그래프","전 영역에서 $1/r^2$에 비례하는 그래프"]'::jsonb, '1', '균일하게 대전된 구에서 내부 전계는 거리 $r$에 비례($E \propto r$)하고, 외부 전계는 거리의 제곱에 반비례($E \propto 1/r^2$)합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 17, '무한히 넓은 평면 자성체의 앞 $a[m]$ 거리의 경계면에 평행하게 무한히 긴 직선 전류 $I[A]$가 흐를 때, 단위 길이당 작용력은 몇 $[N/m]$인가?', '["$\\frac{\\mu_0 I^2}{4\\pi a} (\\frac{\\mu + \\mu_0}{\\mu - \\mu_0})$","$\\frac{\\mu_0 I^2}{2\\pi a} (\\frac{\\mu + \\mu_0}{\\mu - \\mu_0})$","$\\frac{\\mu_0 I^2}{4\\pi a} (\\frac{\\mu - \\mu_0}{\\mu + \\mu_0})$","$\\frac{\\mu_0 I^2}{2\\pi a} (\\frac{\\mu - \\mu_0}{\\mu + \\mu_0})$"]'::jsonb, '3', '자성체에 의한 영상전류법을 적용하면 영상전류 $I'' = \frac{\mu - \mu_0}{\mu + \mu_0} I$가 대칭인 $-a$ 지점에 흐릅니다. 두 평행 전류 사이의 거리 $d=2a$에서의 힘 $F = \frac{\mu_0 I I''}{2\pi d} = \frac{\mu_0 I^2}{4\pi a}(\frac{\mu - \mu_0}{\mu + \mu_0})$ 가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 18, '전기 쌍극자에 관한 설명으로 틀린 것은?', '["전계의 세기는 거리의 세제곱에 반비례한다.","전위는 거리의 제곱에 반비례한다.","전계의 세기는 쌍극자 모멘트에 비례한다.","쌍극자 모멘트의 방향은 (+)전하에서 (-)전하 방향이다."]'::jsonb, '4', '전기 쌍극자 모멘트의 방향은 (-)전하에서 시작하여 (+)전하로 향하는 방향으로 정의됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 19, '무한 평면 도체로부터 $2[m]$ 거리에 $4[C]$의 점전하가 있을 때, 도체가 받는 작용력은 몇 $[N]$인가?', '["$4.5 \\times 10^{9}$","$9 \\times 10^{9}$","$1.8 \\times 10^{10}$","$3.6 \\times 10^{10}$"]'::jsonb, '2', '영상전하법에 의해 거리 $2d = 4m$인 곳에 $-4C$의 전하가 있다고 보면, $F = \frac{1}{4\pi \epsilon_0} \frac{Q^2}{(2d)^2} = 9 \times 10^9 \times \frac{4^2}{4^2} = 9 \times 10^9 [N]$ 가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 20, '극판의 간격이 $d$인 평행판 콘덴서에 두께 $t$, 비유전율 $\epsilon_s$인 유전체를 극판에 평행하게 넣었을 때, 전위차 $V$는 어떻게 변화하는가? (단, 공기 중에서의 전위차를 $V_0$라 한다.)', '["$V_0(1 - \\frac{t}{\\epsilon_s d})$","$\\frac{V_0 t}{d}(1 - \\frac{1}{\\epsilon_s})$","$V_0(1 + \\frac{t}{\\epsilon_s d})$","$V_0 [1 - \\frac{t}{d}(1 - \\frac{1}{\\epsilon_s})]$"]'::jsonb, '4', '유전체가 들어간 경우의 전계는 공기 중 전계 $E_0$에 대하여 유전체 내부에서 $E_0/\epsilon_s$가 됩니다. 전위차 $V = E_0(d-t) + \frac{E_0}{\epsilon_s}t$ 를 계산하여 정리하면 $V = V_0 [1 - \frac{t}{d}(1 - \frac{1}{\epsilon_s})]$ 가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 21, '150[kVA] 단상변압기 3대를 △-△ 결선으로 사용하다가 1대의 고장으로 V-V결선하여 사용하면 약 몇 [kVA] 부하까지 걸 수 있겠는가?', '["","","","60"]'::jsonb, '4', 'V-V 결선 시의 출력 $P_V = \sqrt{3} P_1$입니다. 따라서 $150 \times \sqrt{3} \approx 259.8 [kVA]$이므로 약 260[kVA]까지 부하를 걸 수 있습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 22, '송전계통의 안정도를 증진시키는 방법이 아닌 것은?', '["전압변동을 적게 한다.","제동저항기를 설치한다.","선로의 리액턴스를 크게 한다.","고속도 재폐로 방식을 채택한다."]'::jsonb, '3', '안정도를 증진시키기 위해서는 선로의 리액턴스를 **작게** 해야 합니다. 이를 위해 복도체 사용, 직렬 콘덴서 설치 등의 방법을 사용합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 23, '수력발전소에서 수차의 비속도(Specific speed)의 정의로 옳은 것은?', '["수차의 회전속도와 낙하속도의 비","m 낙차로 1kW의 출력을 발생시키는데 필요한 회전수","m 낙차로 1m³/s의 유량을 유입시키는데 필요한 회전수","단위 유효낙차로 단위 출력을 발생시키는 수차의 낙하속도"]'::jsonb, '2', '비속도(특유속도)는 수차가 1m의 유효낙차에서 1kW의 출력을 발생시키는 데 필요한 회전속도를 말합니다. 공식은 $N_s = N \frac{P^{1/2}}{H^{5/4}}$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 24, '차단기의 차단 과정을 설명한 것 중 틀린 것은?', '["고장전류를 OCR이 검출한다.","트립코일이 여자되어 차단기를 개로한다.","발생된 아크를 신속하게 소호한다.","모노그램 등으로 원격 조작한다."]'::jsonb, '4', '차단기의 자동 차단 과정은 ''고장 검출(OCR) → 트립코일 여자 → 기구적 개로 → 아크 소호''의 순서로 이루어집니다. 모노그램(계통도) 등을 통한 원격 조작은 일반적인 자동 차단 과정에 포함되지 않는 설명입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 25, '3상 결선 변압기의 단상 운전에 의한 소손방지 목적으로 설치하는 계전기는?', '["단락 계전기","결상 계전기","지락 계전기","과전압 계전기"]'::jsonb, '2', '3상 회로에서 한 상이 끊어지는 결상 사고 발생 시 모터나 변압기가 과열되어 소손되는 것을 방지하기 위해 결상 계전기(Phase-failure relay)를 사용합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 26, '인터록(interlock)의 기능에 대한 설명으로 맞는 것은?', '["조작자의 의중에 따라 개폐되어야 한다.","차단기가 열려 있어야 단로기를 닫을 수 있다.","차단기가 닫혀 있어야 단로기를 닫을 수 있다.","차단기와 단로기를 별도로 닫고, 열 수 있어야 한다."]'::jsonb, '2', '인터록은 오조작을 방지하기 위한 안전 장치로, 반드시 차단기(CB)가 열려(OFF) 있는 상태에서만 단로기(DS)를 조작할 수 있도록 제한하는 기능입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 27, '[그림 참고] 그림과 같은 22[kV] 3상 3선식 전선로의 P점에 단락이 발생하였다면 3상 단락전류는 약 몇 [A]인가? 단, %리액턴스는 8[%]이며 저항분은 무시한다. (기준용량 20,000[kVA])', '["561","560","64","684"]'::jsonb, '1', '단락전류 $I_s = \frac{100}{\%Z} I_n = \frac{100}{\%Z} \times \frac{P}{\sqrt{3}V}$ 공식에 대입하면, $I_s = \frac{100}{8} \times \frac{20000}{\sqrt{3} \times 22} \approx 12.5 \times 524.8 \approx 6561 [A]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 28, '전력계통에서 내부 이상전압의 크기가 가장 큰 경우는?', '["유도성 소전류 차단시","수차발전기의 부하 차단시","무부하 선로 충전전류 차단시","송전선로의 부하 차단기 투입시"]'::jsonb, '3', '무부하 선로의 충전전류를 차단할 때 발생하는 이상전압은 재점호에 의해 매우 커지며, 이는 내부 이상전압 중 최대 수준(대략 상전압의 3~4배)에 이릅니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 29, '화력 발전소에서 재열기의 목적은?', '["급수예열","석탄건조","공기예열","증기가열"]'::jsonb, '4', '재열기(Reheater)는 고압 터빈에서 일을 마친 증기를 다시 보일러로 보내어 가열함으로써 열효율을 증대시키기 위한 장치입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 30, '송전선로의 각 상전압이 평형되어 있을 때 3상 1회선 송전선의 작용정전용량[$\mu$F/km]을 옳게 나타낸 것은? 단, r은 도체의 반지름[m] D는 도체의 등가선간거리[m]이다.', '["$\\frac{0.02413}{\\log_{10} \\frac{D}{r}}$","$\\frac{0.2413}{\\log_{10} \\frac{D}{r}}$","$\\frac{0.02413}{\\log_{10} \\frac{D^2}{r}}$","$\\frac{0.2413}{\\log_{10} \\frac{D^2}{r}}$"]'::jsonb, '1', '3상 1회선 송전선의 작용 정전용량 공식은 $C_w = C_s + 3C_m = \frac{0.02413}{\log_{10} \frac{D}{r}} [\mu F/km]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 31, '플리커 현상을 줄이기 위한 전력 공급측의 방안이 아닌 것은?', '["공급전압을 낮춘다.","전용 변압기로 공급한다.","단독 공급 계통을 구성한다.","단락용량이 큰 계통에서 공급한다."]'::jsonb, '1', '플리커 현상을 줄이기 위해서는 전압 강하를 최소화해야 하므로 공급전압을 **높이는 것**이 올바른 방안입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 32, '송전선로에서 송전전력, 거리, 전력손실율과 전선의 밀도가 일정하다고 할 때, 전선 단면적$A[mm^2]$는 전압 $V[V]$와 어떤 관계에 있는가?', '["V에 비례한다.","V²에 비례한다.","/V에 비례한다.","/V²에 비례한다."]'::jsonb, '4', '전력손실 $P_L = \frac{3 P^2 R}{V^2 \cos^2 \theta} = \frac{3 P^2 \rho L}{V^2 A \cos^2 \theta}$에서 전선 단면적 $A = \frac{3 P^2 \rho L}{V^2 P_L \cos^2 \theta}$이므로 $A \propto \frac{1}{V^2}$ 관계가 성립합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 33, '동기조상기에 관한 설명으로 틀린 것은?', '["동기전동기의 V특성을 이용하는 설비이다.","동기전동기를 부족여자로 하여 컨덕턴스로 사용한다.","동기전동기를 과여자로 하여 콘덴서로 사용한다.","송전계통의 전압을 일정하게 유지하기 위한 설비이다."]'::jsonb, '2', '동기조상기는 부족여자로 운전할 경우 **리액터**(지상 전류)로 작용하여 전압이 오를 때 낮추는 역할을 합니다. 컨덕턴스로 사용한다는 설명은 틀렸습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 34, '비등수형 원자로의 특색이 아닌 것은?', '["열교환기가 필요하다.","기포에 의한 자기 제어성이 있다.","방사능 때문에 증기는 완전히 기수분리를 해야 한다.","순환펌프로서는 급수펌프뿐이므로 펌프동력이 작다."]'::jsonb, '1', '비등수형(BWR) 원자로는 원자로 내에서 직접 물을 끓여 증기를 발생시키므로 별도의 열교환기(증기발생기)가 필요 없습니다. 반면 가압경수형(PWR)은 열교환기가 필요합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 35, '[그림 참고] 그림과 같은 단거리 배전선로의 송전단 전압 6600[V], 역률은 0.9이고, 수전단 전압 6100[V], 역률 0.8 일 때 회로에 흐르는 전류 I[A]는? 단, $E_S$ 및 $E_r$은 송·수전단 대지전압이며, r=20[$\Omega$], x=10[$\Omega$]이다.', '["","5","","5"]'::jsonb, '3', '송전단 전력 $P_S = V_S I \cos \theta_1$, 수전단 전력 $P_r = V_r I \cos \theta_2$라고 할 때, 전력손실 $P_L = P_S - P_r = I^2 r$이 성립합니다. 따라서 $(6600 \times I \times 0.9) - (6100 \times I \times 0.8) = I^2 \times 20$ 식에서 $(5940 - 4880)I = 20I^2$이므로 $1060 = 20I$, 즉 $I = 53[A]$가 됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 36, '피뢰기의 제한전압이란?', '["충격파의 방전개시전압","상용주파수의 방전개시전압","전류가 흐르고 있을 때의 단자전압","피뢰기 동작 중 단자전압의 파고값"]'::jsonb, '4', '제한전압은 피뢰기가 동작하여 충격파 전류를 방전하고 있을 때, 피뢰기 단자 사이에 남게 되는 충격 전압의 파고값을 의미합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 37, '단락용량 5000[MVA]인 모선의 전압이 154[kV]라면 등가 모선임피던스는 약 몇 [$\Omega$]인가?', '["54","74","",""]'::jsonb, '2', '단락용량 $P_s = \frac{V^2}{Z}$ 식에서 $Z = \frac{V^2}{P_s}$입니다. 따라서 $Z = \frac{(154 \times 10^3)^2}{5000 \times 10^6} \approx 4.743 [\Omega]$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 38, '피뢰기가 그 역할을 잘 하기 위하여 구비되어야 할 조건으로 틀린 것은?', '["충격방전개시전압이 낮을 것","상용주파방전개시전압이 낮을 것","제한전압이 낮을 것","속류 차단능력이 충분할 것"]'::jsonb, '2', '상용주파방전개시전압은 정상적인 운전 전압에서 피뢰기가 오동작하지 않도록 **충분히 높아야** 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 39, '저압배전선로에 대한 설명으로 틀린 것은?', '["저압 뱅킹 방식은 전압변동을 경감할 수 있다.","밸런서(balancer)는 단상 2선식에 필요하다.","배전선로의 부하율이 F일 때 손실계수는 F와 F²의 중간 값이다.","수용률이란 최대수용전력을 설비용량으로 나눈 값을 퍼센트로 나타낸 것이다."]'::jsonb, '2', '저압 밸런서는 단상 **3선식** 선로에서 부하의 불평형으로 인해 발생하는 중성선과 각 전압선 사이의 전압 불평형을 방지하기 위해 사용됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 40, '[그림 참고] 전력계통의 154[kV] 송전선로에서 고장 지락 임피던스 $Z_{gf}$ 를 통해서 1선 지락고장이 발생되었을 때 고장점에서 본 영상 %임피던스는? 단, 모든 임피당스는 100[MVA] 기준으로 환산한 값임.', '["Z₀ = Zₗ + Zₜ + Z_gf","Z₀ = Zᵢ + Zₜ + Z_gf","Z₀ = Zₗ + Zₜ + 3Z_gf","Z₀ = Zₗ + Zₜ + Z_gf + Z_G + Z_GN"]'::jsonb, '3', '1선 지락 고장 시 지락 지점의 임피던스 $Z_{gf}$에는 영상전류 $I_0$가 아닌 대지전류 $3I_0$가 흐르므로, 영상 성분으로 환산한 단상 임피던스는 $3Z_{gf}$가 됩니다. 따라서 전체 영상 임피던스는 $Z_0 = Z_l + Z_t + 3Z_{gf}$입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 41, '정전압 계통에 접속된 동기발전기의 여자를 약하게 하면?', '["출력이 감소한다.","전압이 강하한다.","앞선 무효전류가 증가한다.","뒤진 무효전류가 증가한다."]'::jsonb, '3', '동기발전기의 여자를 약하게 하면(부족여자), 유도 기전력이 감소하여 단자 전압과의 위상차에 의해 앞선 전류(진상 무효전류)가 흐르게 됩니다. 위상특성곡선(V곡선)에 따라 발전기에서 부족여자 운전 시 진상 전류가 흐릅니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 42, '다이오드를 사용하는 정류회로에서 과대한 부하전류로 인하여 다이오드가 소손될 우려가 있을 때 가장 적절한 조치는 어느 것인가?', '["다이오드를 병렬로 추가한다.","다이오드를 직렬로 추가한다.","다이오드를 직·병렬로 추가한다.","다이오드에 기전력을 높인다."]'::jsonb, '1', '다이오드를 병렬로 연결하면 전류를 분담하여 흘릴 수 있으므로 과대한 부하 전류로부터 다이오드를 보호할 수 있습니다. (직렬 연결은 과전압으로부터 보호하기 위한 전압 분담용입니다.)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 43, '직류 발전기의 외부 특성곡선에서 나타내는 관계로 옳은 것은?', '["계자전류와 단자전압","부하전류와 단자전압","계자전류와 유도기전력","부하전류와 유도기전력"]'::jsonb, '2', '외부 특성곡선은 발전기가 회전하고 있을 때 부하 전류 $I$와 단자 전압 $V$ 사이의 관계를 나타내는 곡선입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 44, '직류기의 전기자 반작용에 의한 영향이 아닌 것은?', '["자속이 감소하므로 유기기전력이 감소한다.","발전기의 경우 회전방향으로 전기적 중성축이 이동한다.","전동기의 경우 회전방향과 반대방향으로 전기적 중성축이 이동한다.","브러시에 의해 단락된 코일에는 기전력이 발생하므로 브러시 사이의 유기기전력이 증가한다."]'::jsonb, '4', '전기자 반작용은 주자속을 감소시키고 중성축을 이동시켜 브러시에서 불꽃(Sparking)을 발생시키며 결과적으로 단자 전압을 하강시킵니다. 브러시 사이의 유기기전력이 증가하는 현상은 발생하지 않습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 45, '부하 전압 2000[V], 맥동률 3[%]인 정류 회로에서 교류분 진폭은 약 몇 [V]인가?', '["","","",""]'::jsonb, '4', '맥동률은 직류 평균 전압에 대한 교류 성분의 비율을 의미합니다. $\text{맥동률} = \frac{\text{교류분 실효값}}{\text{직류분 평균값}} \times 100[\%]$ 이므로, $\text{교류 성분} = 2000 \times 0.03 = 60[V]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 46, '100[kVA], 3300/200[V] 3상 변압기의 정격전류는 약 몇 [A]인가?', '["7.5","5","","7"]'::jsonb, '1', '3상 변압기의 정격 전류 $I_n$은 $\frac{P}{\sqrt{3}V}$로 계산합니다. $I_n = \frac{100 \times 10^3}{\sqrt{3} \times 3300} \approx 17.5[A]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 47, '3상 유도 전동기의 단자 전압 200[V], 선전류 21.5[A], 역률 0.86, 효율 0.85일 때 출력은 약 몇 [W]인가?', '["627","4","3","1"]'::jsonb, '2', '3상 출시는 $P = \sqrt{3} V I \cos\phi \eta$ 입니다. $P = \sqrt{3} \times 200 \times 21.5 \times 0.86 \times 0.85 \approx 5444.3[W]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 48, '변압비 3000/100[V]인 단상변압기 2대의 고압측을 그림과 같이 직렬로 3300[V] 전원에 연결하고, 저압측에 각각 5[\Omega], 7[\Omega]의 저항을 접속하였을 때, 고압측의 단자전압 $E_1$은 약 몇 [V]인가? [그림 참고]', '["71","60","75","925"]'::jsonb, '3', '변압기를 거쳐 부하로 전달되는 전압은 부하의 저항 비율로 분배됩니다. 전체 전압 3300V에 대하여 $E_1$ 측 부하 저항이 5, 다른 쪽이 7이므로, $E_1 = \frac{5}{5+7} \times 3300 = 1375[V]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 49, '교류기에서 유기기전력의 특정 고조파분을 제거하고 또 권선을 절약하기 위하여 자주 사용되는 권선법은?', '["전절권","분포권","집중권","단절권"]'::jsonb, '4', '단절권은 고조파를 제거하여 기전력의 파형을 개선하고, 권선 끝부분의 길이를 짧게 하여 동(Copper) 소모를 줄일 수 있는 권선법입니다. 고조파 제거를 병행하기 위해 분포권도 사용되나 권선 절약 특징은 단절권이 더 큽니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 50, '12극의 3상 동기발전기의 기계각 15도에 상응하는 전기각은 몇 도인가?', '["","5","",""]'::jsonb, '4', '전기각 $\theta_e$와 기계각 $\theta_m$의 관계식 $\theta_e = \frac{P}{2}\theta_m$ 을 사용합니다. $\theta_e = \frac{12}{2} \times 15^\circ = 90^\circ$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 51, '4극, 60[Hz]의 유도전동기가 슬립 5[%]로 전부하 운전 하고 있을 때 2차 권선의 손실이 94.25[W]라고 하면 토크는 약 몇 [N\cdot m]인가?', '["","","",""]'::jsonb, '3', '준비식: 2차 입력 $P_2 = \frac{P_{c2}}{s} = \frac{94.25}{0.05} = 1885[W]$, 동기 동토크 $\omega_s = \frac{2 \pi f}{P/2} = \frac{2 \pi \times 60}{2} = 60\pi$. 토크 $T = \frac{P_2}{\omega_s} = \frac{1885}{60\pi} \approx 10[N \cdot m]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 52, '단상 변압기에 정현파 유기기전력을 유기하기 위한 여자전류의 파형은?', '["정현파","제3고조파를 포함하는 왜형파","제5고조파를 포함하는 왜형파","감쇠 파형"]'::jsonb, '2', '철심의 자기 포화와 히스테리시스 현상으로 인해 정현파 기전력을 얻으려면 여자 전류에 제3고조파 성분이 포함된 왜형파가 흘러야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 53, '선형(LINEAR) 전동기와 회전형 전동기를 비교했을 때 틀린 것은?', '["회전형에 비해 공극이 작다.","직선 운동에 적합하다.","구조가 간단하고 소음이 적다.","효율과 역률이 낮다."]'::jsonb, '1', '선형 전동기(Linear Motor)는 기계적 구조의 특성상 회전형 전동기보다 공극(Air gap)이 훨씬 넓게 형성되어야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 54, '변압기 전일 효율을 최대가 되게 하기 위한 조건은?', '["하루 중 무부하손의 합 = 하루 중 부하손의 합","선로 임피던스 최소","철손 / 동손 = 1","전부하 시 전압 강하 최소"]'::jsonb, '1', '전일 효율(All-day efficiency)이 최대가 되려면 철손(무부하손)의 24시간 합계가 부하 운전 시간 동안 발생하는 동손(부하손)의 합계와 같아야 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 55, '유도전동기를 정격상태로 사용 중, 전압이 10[%] 상승하면 다음과 같은 특성의 변화가 있다. 틀린 것은? 단, 부하는 일정 토크라고 가정한다.', '["온도 상승이 감소한다.","부하 전류가 증가한다.","역률이 좋아진다.","효율이 약간 좋아진다."]'::jsonb, '2', '전압 $V$가 상승하면 자속 $\phi$가 증가하여 철손 및 자화 전류가 증가하므로 역률이 하강합니다. 또한 일정한 토크와 출력을 위해 부하 전류는 감소해야 합니다. 따라서 2번과 3번이 틀린 설명으로 실제 시험에서는 복수 정답 처리되었습니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 56, '수하특성(Drooping characteristic)을 가지고 있는 발전기는?', '["분권 발전기","타여자 발전기","차동 복권 발전기","가동 복권 발전기"]'::jsonb, '3', '차동 복권 발전기는 부하 전류가 증가하면 전압이 급격히 감소하는 수하 특성을 가지고 있어 아크 용접기 등에 사용됩니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 57, '직류기 권선법에 대한 설명 중 틀린 것은?', '["단중 파권은 균압환이 필요하다.","단중 중권의 병렬회로 수는 극수와 같다.","저전류ㆍ고전압 출력은 파권이 유리하다.","단중 파권의 유기전압은 단중 중권의 $P/2$배이다."]'::jsonb, '1', '파권(Wave winding)은 병렬 회로 수가 항상 2이므로 전위 불평형이 발생하지 않아 균압환이 불필요합니다. 균압환은 병렬 회로 수가 극수와 같은 중권에서 4극 이상일 때 필요합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 58, '스테핑 모터의 일반적인 특징으로 틀린 것은?', '["기동ㆍ정지 특성은 나쁘다.","회전각은 입력펄스 수에 비례한다.","회전속도는 입력펄스 주파수에 비례한다.","고속 응답이 좋고, 고출력의 운전이 가능하다."]'::jsonb, '1', '스테핑 모터의 주요 장점은 기동, 정지 및 역회전 시의 정밀도와 응답 특성이 매우 우수하다는 점입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 59, '철손 1.6[kW], 전부하동손 2.4[kW]인 변압기에는 약 몇 [%] 부하에서 효율이 최대로 되는가?', '["","5","7",""]'::jsonb, '1', '최대 효율 부하율 $m = \sqrt{\frac{P_i}{P_c}}$ 입니다. $m = \sqrt{\frac{1.6}{2.4}} = \sqrt{\frac{2}{3}} \approx 0.816 = 81.6[\%]$ 입니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 1, 60, '동기기 제동권선(Damper winding)의 주요 작용은?', '["역률 개선","난조 방지","전압 조정","위상 제어"]'::jsonb, '2', '제동권선은 회전자의 난조(Hunting) 현상을 방지하고, 기온 시에 기동 토크를 발생시키는 역할을 합니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 1, '회로에 흐르는 전류의 크기는 저항에 ( ㉮ )하고, 가해진 전압에 ( ㉯ )한다. [그림 참고]', '["비례, ㉯ 반비례","비례, ㉯ 비례","반비례, ㉯ 비례","반비례, ㉯ 반비례"]'::jsonb, '3', '옴의 법칙 ($I = V/R$)에 의해 전류($I$)는 저항($R$)에 반비례하고 전압($V$)에 비례한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 2, '은(Ag)의 전기 화학 당량은 약 $1.118 \times 10^{-3}[g/C]$이다. 어떤 전해조에서 1시간 동안 $10[A]$의 전류를 흘렸다면 전착되는 은의 양은 약 몇 $[g]$인가?', '["8","5","8","5"]'::jsonb, '2', '전착량 $W = kIt = 1.118 \times 10^{-3} \times 10 \times 3600 \approx 40.25[g]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 3, '반지름 $r[m]$, 권수 $N$회의 원형 코일에 전류 $I[A]$가 흐를 때, 그 중심점의 자기장의 세기 $H[At/m]$는?', '["$NI / 2r$","$NI / r$","$NI / 2 \\pi r$","$NI / \\pi r$"]'::jsonb, '1', '원형 코일 중심의 자기장 세기 공식은 $H = \frac{NI}{2r}$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 4, '$3[V]$의 전위차로 $300[C]$의 전하가 이동할 때 한 일은 몇 $[J]$인가?', '["","","","700"]'::jsonb, '3', '일 $W = QV = 300 \times 3 = 900[J]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 5, '충전된 대전체를 대지에 연결하면 대전체는 어떻게 되는가?', '["방전한다.","반발한다.","충전이 계속된다.","반발과 흡인을 반복한다."]'::jsonb, '1', '대전체를 접지하면 전하가 대지로 흘러가 방전된다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 6, '반자성체 물질의 특색을 나타낸 것은? (단, $\mu_s$는 비투자율이다.)', '["$\\mu_s \\gg 1$","$\\mu_s \u003e 1$","$\\mu_s = 1$","$\\mu_s \u003c 1$"]'::jsonb, '4', '반자성체는 비투자율이 1보다 작다. (상자성체는 $\mu_s > 1$, 강자성체는 $\mu_s \gg 1$)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 7, '단면적 $S[m^2]$, 길이 $l[m]$, 투자율 $\mu[H/m]$인 자로의 자기 저항 $R_m[At/Wb]$은?', '["$l / \\mu S$","$\\mu l / S$","$l / S$","$S / \\mu l$"]'::jsonb, '1', '자기 저항 $R_m = \frac{l}{\mu S}$이다. 이는 전기 저항 $R = \rho \frac{l}{S} = \frac{l}{\sigma S}$와 유사한 형태이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 8, '구리(연동)의 온도가 $20[℃]$에서 $80[℃]$로 상승하면 저항은 약 몇 배로 되는가? (단, 구리의 온도계수 $\alpha_{20} = 0.00393$이다.)', '["","","5",""]'::jsonb, '2', '$R_t = R_0[1 + \alpha(t_2-t_1)] = 1 \times [1 + 0.00393(80-20)] \approx 1.2358 \approx 1.24$배.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 9, '유전율의 단위로 옳은 것은?', '["$[F/m]$","$[H/m]$","$[Wb/m]$","$[V/m]$"]'::jsonb, '1', '유전율($\epsilon$)의 단위는 $[F/m]$ (Farad per meter)이다. 투자율($\mu$)은 $[H/m]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 10, '그림의 회로에서 $0.5[Ω]$의 저항에 흐르는 전류는 몇 $[A]$인가? [그림 참고]', '["","","",""]'::jsonb, '4', '1. 병렬 부분($1[\Omega], 3[\Omega]$)의 합성저항 $R_p = \frac{1 \times 3}{1+3} = 0.75[\Omega]$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 11, 'RL 직렬회로에서 저항 $R = 8[Ω]$, 유도 리액턴스 $X_L = 6[Ω]$일 때, 임피던스의 크기는?', '["","","","8"]'::jsonb, '2', '$Z = \sqrt{R^2 + X_L^2} = \sqrt{8^2 + 6^2} = 10[Ω]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 12, '자기 인덕턴스 $L[H]$에 흐르는 전류가 $0.1$초 동안에 $5[A]$에서 $15[A]$로 변했을 때 코일에 유도되는 기전력이 $100[V]$였다. 이때 자기 인덕턴스 $L$은 몇 $[H]$인가?', '["","","",""]'::jsonb, '2', '$e = L \frac{\Delta I}{\Delta t} \implies 100 = L \times \frac{15-5}{0.1} = L \times 100 \implies L = 1[H]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 13, '정현파 교류 기전력의 실효값은 최대값의 약 몇 $[\%]$인가?', '["6.7","","7","7"]'::jsonb, '4', '실효값($V_{rms}$)은 최대값($V_m$)의 $\frac{1}{\sqrt{2}} \approx 0.707$배이므로 $70.7[\%]$이다. 평균값은 약 $63.7[\%]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 14, '두 금속을 접속하여 여기에 전류를 흘리면 접속점에서 열의 발생 또는 흡수가 일어나는 현상은?', '["제벡 효과","펠티에 효과","톰슨 효과","홀 효과"]'::jsonb, '2', '펠티에 효과는 두 금속 접점에 전류를 흘릴 때 열의 출입이 일어나는 현상(전자냉각 등에 활용)이다. 제벡 효과는 반대로 온도차에 의해 기전력이 발생하는 현상이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 15, '그림의 회로에서 $a, b$ 사이의 합성 저항은 몇 $[Ω]$인가? [그림 참고]', '["","","",""]'::jsonb, '2', '브리지 회로의 평형 조건($1 \times 3 = 1 \times 3$)을 만족하므로 중앙의 $2[\Omega]$ 저항에는 전류가 흐르지 않아 무시할 수 있다.
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 16, '$3$상 $220[V]$ 선간 전압을 $\Delta$부하에 가했을 때 각 상의 임피던스가 $Z = 8 + j6[Ω]$이라면 선전류는 약 몇 $[A]$인가?', '["","8","","6"]'::jsonb, '2', '1. 상전압 $V_p = V_l = 220[V]$
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 17, '전해액에 전류가 흘러서 화학 변화를 일으키는 현상을 무엇이라 하는가?', '["정전 유도","전자 유도","전기 분해","열전 현상"]'::jsonb, '3', '전류를 통해 화학 반응을 유도하는 것이 전기 분해다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 18, '진공 중에 $+m[Wb]$의 자극으로부터 나오는 총 자력선의 수는?', '["$m \\mu_0$","$m / \\mu_0$","$\\mu_0 / m$","$1 / \\mu_0 m$"]'::jsonb, '2', '매질 내의 총 자력선 수 $N = \frac{m}{\mu_0}$이다. (자속 수 $\Phi = m$)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 19, '유도 기전력은 자신이 발생 원인이 되는 자속의 변화를 방해하려는 방향으로 발생한다. 이것은 어느 법칙인가? [그림 참고]', '["렌츠의 법칙","패러데이의 법칙","플레밍의 오른손 법칙","비오-사바르의 법칙"]'::jsonb, '1', '유도 기전력의 크기는 패러데이 법칙, 방향은 렌츠의 법칙이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 20, '다음 중 비투자율이 가장 큰 것은?', '["은","구리","알루미늄","강철"]'::jsonb, '4', '강철은 강자성체로 비투자율이 1보다 매우 크다. 은, 구리 등은 반자성체 또는 상자성체로 비투자율이 1 근처이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 21, '동기 전동기의 난조를 방지하기 위해 자극면에 설치하는 권선은?', '["제동 권선","전기자 권선","계자 권선","보상 권선"]'::jsonb, '1', '제동 권선(Damper winding)은 난조 방지 및 자기동 토크 발생을 위해 설치한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 22, '직류 발전기에서 전기자 반작용을 방지하기 위한 가장 유효한 방법은?', '["탄소 브러시 사용","보극 설치","보상 권선 설치","균압 고리 설치"]'::jsonb, '3', '전기자 반작용을 상쇄하기 위해 전기자 권선과 반대 방향으로 전류를 흘리는 보상 권선(Compensating winding)이 가장 유효하다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 23, '변압기 부하 전류 및 전압이 일정하고 주파수가 낮아졌을 때의 현상으로 옳은 것은?', '["철손 증가","철손 감소","절연 내력 감소","절연 내력 증가"]'::jsonb, '1', '$V = 4.44 f N \Phi$에서 전압($V$)이 일정할 때 주파수($f$)가 낮아지면 자속($\Phi$)이 증가하며, 이에 따라 철손(특히 히스테리시스손)이 증가한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 24, '슬립 $4[\%]$인 유도 전동기의 회전자 속도가 $1152[rpm]$이면 동기 속도는 몇 $[rpm]$인가?', '["0","0","500","800"]'::jsonb, '2', '$N = N_s(1-s) \implies 1152 = N_s(1-0.04) \implies N_s = \frac{1152}{0.96} = 1200[rpm]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 25, '직류 전동기의 속도 제어 방법 중 광범위한 속도 제어가 가능하며 운전 효율이 좋은 방법은?', '["전압 제어","계자 제어","저항 제어","직병렬 제어"]'::jsonb, '1', '전압 제어(워드 레오나드 방식 등)는 효율이 좋고 광범위한 속도 조절이 가능하다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 26, '계기용 변압기의 $2$차측 정격 전압은 몇 $[V]$인가?', '["","","",""]'::jsonb, '2', 'PT($2$차측)의 표준 정격 전압은 $110[V]$이다. (CT $2$차측은 $5[A]$)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 27, 'SCR $2$개를 역병렬로 접속한 모양의 소자로 교류 스위칭용인 것은?', '["GTO","SCS","SSS","Triac"]'::jsonb, '4', '트라이액(Triac)은 양방향 $3$단자 사이리스터로 교류 전력 제어에 사용된다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 28, '발전기의 규약 효율을 나타낸 식은? [그림 참고]', '["$(입력 / 출력) \\times 100$","$(출력 / 입력) \\times 100$","$(출력 / (출력 + 손실)) \\times 100$","$( (입력 - 손실) / 입력 ) \\times 100$"]'::jsonb, '3', '발전기(기기)의 규약 효율 = $\frac{출력}{출력 + 손실} \times 100$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 29, '권수가 $200$회인 코일에 $2[A]$의 전류가 흘러서 $0.01[Wb]$의 자속이 코일을 지난다. 이 코일의 자기 인덕턴스$[H]$는?', '["5","","5",""]'::jsonb, '2', '$L = \frac{N\Phi}{I} = \frac{200 \times 0.01}{2} = 1[H]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 30, '병렬 운전 중인 두 대의 $3$상 동기 발전기 사이에 무효 순환 전류가 흐르는 경우는?', '["기전력의 크기가 다를 때","기전력의 위상이 다를 때","기전력의 파형이 다를 때","회전수가 다를 때"]'::jsonb, '1', '기전력의 크기가 다르면 무효 횡류(무효 순환 전류)가 흐른다. 위상이 다르면 유효 횡류(동기화 전류)가 흐른다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 31, '직류기에서 정류를 좋게 하기 위한 방법으로 틀린 것은?', '["보극을 설치한다.","브러시 접촉 저항을 작게 한다.","리액턴스 전압을 작게 한다.","브러시를 중성축으로 이동시킨다."]'::jsonb, '2', '양호한 정류를 위해서는 브러시 접촉 저항을 **크게** (저항 정류) 해야 한다. 또한 보극 설치나 리액턴스 전압 감소(전압 정류)가 필요하다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 32, '유도 전동기의 동기 속도 $N_s$와 주파수 $f$의 관계는?', '["비례한다.","반비례한다.","제곱에 비례한다.","주파수와 관계없다."]'::jsonb, '1', '$N_s = \frac{120f}{P}$이므로 동기 속도는 주파수에 비례한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 33, '동기 발전기의 무무하 포화 곡선은 무엇과 무엇의 관계인가?', '["계자 전류와 단자 전압","계자 전류와 유도 기전력","부하 전류와 단자 전압","부하 전류와 유도 기전력"]'::jsonb, '2', '무부하 포화 곡선은 계자 전류($I_f$)와 무부하 단자 전압($V=$유도 기전력 $E$)의 관계를 나타낸다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 34, '직류 전동기에 대한 설명으로 틀린 것은?', '["타여자 전동기는 전압 제어가 용이하다.","분권 전동기는 정속도 특성을 갖는다.","직권 전동기는 시동 토크가 작다.","가동 복권 전동기는 부하가 늘면 속도가 저하한다."]'::jsonb, '3', '직권 전동기는 토크가 전류의 제곱에 비례하므로 시동 토크가 매우 크다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 35, '변압기 내부 고장 보호용으로 사용되는 계전기는?', '["차동 계전기","거리 계전기","과전압 계전기","주파수 계전기"]'::jsonb, '1', '차동 계전기 또는 비율 차동 계전기는 변압기 내부 고장(층간 단락 등) 보호에 사용된다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 36, '반도체 소자 중 $3$단자 사이리스터가 아닌 것은?', '["SCR","GTO","Triac","SCS"]'::jsonb, '4', 'SCS(Silicon Controlled Switch)는 $4$단자 소자이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 37, '$3$상 유도 전동기의 기동 방법 중 기동 토크가 가장 큰 것은?', '["직입 기동","Y-$\\Delta$ 기동","기동 보상기법","전압 제어법"]'::jsonb, '1', '직입 기동(전전압 기동)은 전압을 낮추지 않고 그대로 가하므로 기동 토크가 감소하지 않아 가장 크다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 38, '동기기의 안정도 향상 대책이 아닌 것은?', '["리액턴스를 작게 한다.","관성 모멘트를 크게 한다.","속응 여자 방식을 채용한다.","단락비를 작게 한다."]'::jsonb, '4', '안정도를 향상시키려면 단락비를 **크게** 해야 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 39, '권선형 유도 전동기의 속도 제어 방법은?', '["극수 변환법","주파수 제어법","차 저항 제어법","차 전압 제어법"]'::jsonb, '3', '권선형은 회전자에 슬립링이 있어 외부 가변 저항(2차 저항)을 통해 속도를 조절할 수 있다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 40, '슬립 $s$로 운전 중인 유도 전동기에서 등가 부하 저항은 $2$차 저항 $r_2$의 몇 배인가?', '["$(1-s) / s$","$s / (1-s)$","$(1+s) / s$","$s / (1+s)$"]'::jsonb, '1', '등가 부하 저항 $R = \frac{1-s}{s} r_2$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 41, '옥내 배선 공사에서 절연 전선의 피복을 벗길 때 사용하면 편리한 공구는?', '["플라이어","와이어 스트리퍼","펜치","니퍼"]'::jsonb, '2', '전선 스트리퍼(Wire stripper)는 전선 피복 탈피용 전용 공구이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 42, '합성수지관 공사에서 관 상호 간을 접속할 때 삽입 깊이는 관 바깥지름의 최소 몇 배인가? (단, 접착제를 사용하지 않는 경우이다.)', '["8","","","5"]'::jsonb, '3', '배관 접속 시 삽입 깊이는 접착제 사용 시 $0.8$배, 미사용 시 $1.2$배이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 43, '금속관 공사에서 전선을 관 내에 넣을 때 전선의 총 단면적은 관 내부 단면적의 몇 $[\%]$ 이하가 되어야 하는가? (단, 전선의 굵기 및 종류가 다른 경우이다.)', '["","","8","6"]'::jsonb, '1', '전선의 굵기가 다르면 $32[\%]$, 같으면 $48[\%]$ 이하로 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 44, '폭연성 분진이 있는 장소의 저압 옥내 배선 공사 방법으로 틀린 것은?', '["금속관 공사","케이블 공사","합성수지관 공사","애자 사용 공사"]'::jsonb, '4', '분진 등의 위험 장소에서는 애자 사용 공사가 금지된다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 45, '배전반 및 분전반 설치 시 고려 사항으로 틀린 것은?', '["노출된 장소에 설치한다.","쉽게 조작할 수 있는 장소에 설치한다.","안전한 장소에 설치한다.","습기가 많은 장소에 설치한다."]'::jsonb, '4', '분전반은 습기나 부식성 가스가 있는 곳을 피해서 설치해야 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 46, '전선의 허용 전류는 무엇에 의해 결정되는가?', '["전선의 색상","전선의 허용 온도","전선의 가격","전선의 길이"]'::jsonb, '2', '전선에 흐를 수 있는 최대 전류인 허용 전류는 절연물의 열화가 일어나지 않는 ''허용 온도''에 직접적으로 관련된다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 47, '가공 전선로의 지지물에 지선을 시설할 때 지선의 안전율은 얼마 이상으로 하여야 하는가?', '["5","","5",""]'::jsonb, '3', '지선의 안전율은 $2.5$ 이상, 인장 하중은 $4.31[kN]$ 이상이어야 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 48, '저압 연접 인입선의 시설 기준으로 틀린 것은?', '["인입선에서 분기하는 점으로부터 $100[m]$를 초과하지 않아야 한다.","폭 $5[m]$를 초과하는 도로를 횡단하지 않아야 한다.","옥내를 관통하지 않아야 한다.","전압은 고압이어야 한다."]'::jsonb, '4', '연접 인입선은 오직 ''저압''에서만 시설할 수 있다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 49, '부식성 가스 등이 있는 장소의 시설 방법으로 틀린 것은?', '["절연 전선을 사용한다.","합성수지관 공사를 한다.","애자 사용 공사를 한다.","나전선을 사용한다."]'::jsonb, '4', '부식성 가스가 있는 곳에 부식에 취약한 나전선을 사용하면 안 된다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 50, '가요 전선관 공사에서 관과 관을 접속할 때 사용하는 커플링은?', '["콤비네이션 커플링","앵글 커플링","스트레이트 커플링","스플릿 커플링"]'::jsonb, '4', '관 상호 접속에는 스플릿 커플링, 가요전선관과 금속관 접속에는 콤비네이션 커플링을 사용한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 51, '플로어 덕트 공사의 시설 기준으로 틀린 것은?', '["덕트의 끝부분은 막아야 한다.","박스는 물이 침입하지 않도록 시설해야 한다.","덕트는 제$1$종 접지공사를 해야 한다.","전선은 연선을 사용해야 한다."]'::jsonb, '3', '플로어 덕트는 제$3$종 접지공사 대상이다. (현재 KEC에서는 접지 종별이 폐지되었으나 기출 당시 기준)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 52, '진동이 심한 전기 기계·기구의 단자에 전선을 접속할 때 사용되는 것은?', '["커플링","압착단자","링 슬리브","스프링 와셔"]'::jsonb, '4', '스프링 와셔는 진동에 인한 나사 풀림을 방지한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 53, '고압 가공 전선을 행거로 조가할 때 행거의 간격은 몇 $[cm]$ 이하로 해야 하는가?', '["","","",""]'::jsonb, '1', '조가용선 행거의 간격은 $50[cm]$ 이하이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 54, '흥행장의 옥내 배선의 전압은 몇 $[V]$ 이하이어야 하는가?', '["50","","",""]'::jsonb, '4', '흥행장 사용 전압은 $400[V]$ 이하이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 55, '터널 내 배선 공사 방법으로 틀린 것은?', '["애자 사용 공사","금속관 공사","합성수지관 공사","평형 보호층 공사"]'::jsonb, '4', '터널 내에는 애자, 금속관, 합성수지관 공사가 가능하며 평형 보호층 공사는 해당되지 않는다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 56, '전력용 콘덴서의 설치 목적은?', '["전압 강하 방지","역률 개선","주파수 제어","고조파 제거"]'::jsonb, '2', '콘덴서는 진상 전류를 보충하여 부하의 역률을 개선한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 57, '화약고 내의 배선 명칭으로 틀린 것은?', '["전기 기계 기구는 전선과 전기적으로 결합되어야 한다.","개폐기 및 과전류 차단기는 화약고 밖에 설치한다.","화약고 내에는 전등을 설치할 수 없다.","전로의 대지 전압은 $300V$ 이하로 한다."]'::jsonb, '3', '화약고 내부에도 조명등(백열전등)을 설치할 수 있으나 규정을 따라야 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 58, '다음 중 전구 소켓의 호칭으로 틀린 것은?', '["E10","E17","E26","E50"]'::jsonb, '4', '에디슨 베이스 소켓 규격에는 E10, E14, E17, E26, E39 등이 있으며 E50은 표준 규격이 아니다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 59, '주로 저압 옥내 배선의 분기점에 설치하여 전로를 개폐하는 것은?', '["안전 스위치(배선용 차단기)","단로기","진공 차단기","공기 차단기"]'::jsonb, '1', '옥내 전로 제어 및 보호용으로 배선용 차단기(MCCB)를 가장 흔히 사용한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 2, 60, '감전 방지용 누전 차단기의 정격 감도 전류$[mA]$와 작동 시간[초]으로 옳은 것은?', '["5mA, 0.01초","5mA, 0.03초","mA, 0.03초","mA, 0.1초"]'::jsonb, '3', '인체 감전 보호용은 $30[mA]$ 이하, $0.03$초 이내 작동해야 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 1, '다음 ( ) 안의 알맞은 말은?
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 2, '가장 일반적인 저항기로 세라믹봉에 탄소 덩어리를 소결하여 측정하거나 에나멜선으로 홈을 파서 원하는 저항값을 만든 저항기는?
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 3, '변전소의 전력기기를 시험하기 위하여 회로를 분리하거나 또는 계통의 접속을 바꾸거나 하는 경우에 사���되는 것은?
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 4, '유도 전동기의 $\mathrm{Y}-\Delta$ 기동 시 기동 토크와 기동 전류는 전전압 기동 시의 몇 배가 되는가?
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 5, '변전 설비 전로에 걸리는 전압을 측정할 때 고압 회로와 전압계 사이에 시설하는 것은?
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 6, '고압 가공 인입선이 도로를 횡단하는 경우 노면상 시설하여야 할 높이는 몇 $\mathrm{[m]}$ 이상인가?
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 7, '보호를 요하는 회로의 전류가 어떤 일정한 값(정정값) 이상으로 흘렀을 때 동작하는 계전기는?
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 8, '전주 외등을 전주에 부착하는 경우 전주 외등은 하단으로부터 몇 $\mathrm{[m]}$ 이상 높이에 시설하여야 하는가? (단, 교통 지장이 없는 경우)
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 9, '왜형파를 발생시키는 요인이 아닌 것은?
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 10, '변압기용으로 쓰이는 절연유에 요구되는 성질이 아닌 것은?
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 11, '$10 [\Omega]$의 저항 10개를 접속하여 합성 저항이 최소값을 얻으려면 어떻게 접속하여야 하는가?', '["병렬 접속","직렬 접속","직렬-병렬 접속","브리지 접속"]'::jsonb, '1', '');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 12, '교류 회로에서 양방향 점호(on) 및 소호(off)를 이용하며, 위상 제어를 할 수 있는 소자는?', '["GTO","TRIAC","SCR","IGBT"]'::jsonb, '2', '');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 13, '정격 전압 $220 [V]$인 동기 발전기를 무부하로 운전하였다니 단자 전압이 $253 [V]$가 되었다면 이 발전기의 전압 변동률은 $[%]$인가?', '["","","","5"]'::jsonb, '4', '');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 14, '크레인 고장 또는 호이스트 등의 트롤리선을 애자 공사에 의하여 옥내의 노출 장소에 시설하는 경우 트롤리선의 바닥에서 높이는 $3.5 [m]$ 이상으로 설치하여야 한다.', '["","5","5","5"]'::jsonb, '3', '');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 15, '알루미늄 케이블을 구부리는 경우 그 피복이 손상되지 않도록 하고, 그 피복부의 곡률 반경은 원칙적으로 케이블 외경의 몇 배 이상이어야 하는가?', '["","","",""]'::jsonb, '2', '');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 16, '화약류의 분말이 전기 설비가 발화원이 되어 폭발할 우려가 있는 곳에 시설하는 저압 옥내 배선 공사 방법으로 가장 알맞은 것은?', '["금속관 공사","애자 공사","버스 덕트 공사","합성 수지 몰드 공사"]'::jsonb, '1', '');
