INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 3, 59, '진공 중에 $10 \text{[}\mu\text{C]}$과 $20 \text{[}\mu\text{C]}$의 점전하를 $1 \text{[m]}$의 거리에 놓았을 때 작용하는 힘 $\text{[N]}$은?', '["$18 \\times 10^{-1}$","$2 \\times 10^{-9}$","$9.8 \\times 10^{-9}$","$98 \\times 10^{-9}$"]'::jsonb, '1', '');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 1, '$R_1[\Omega]$, $R_2[\Omega]$, $R_3[\Omega]$의 저항 3개를 직렬 접속했을 때의 합성 저항은?', '["$R = \\frac{R_1 \\cdot R_2 \\cdot R_3}{R_1 + R_2 + R_3}$","$R = \\frac{R_1 R_2 + R_2 R_3 + R_3 R_1}{R_1 + R_2 + R_3}$","$R = R_1 \\cdot R_2 \\cdot R_3$","$R = R_1 + R_2 + R_3$"]'::jsonb, '4', '직렬 합성 저항 $R_0 = R_1 + R_2 + R_3[\Omega]$');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 2, '정상 상태의 원자를 설명한 것으로 틀린 것은?', '["양성자와 전자의 극성은 같다.","원자는 전체적으로 보면 전기적으로 중성이다.","원자를 이루고 있는 양성자의 수는 전자의 수와 같다.","양성자 1개가 지니는 전기량은 전자 1개가 지니는 전기량과 크기가 같다."]'::jsonb, '1', '원자는 양성자와 전자로 구성되어 있으며 양성자는 원자핵 안에 존재하며 $(+)$극성을 띠고, 전자는 원자핵의 중점을 회전하여 $(-)$극성을 띤다. 따라서 양성자와 전자의 극성은 다르다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 3, '2전력계법으로 3상 전력을 측정할 때 지시값이 $P_1 = 200[W]$, $P_2 = 200[W]$이었다. 부하 전력은 $P[W]$은?', '["600","500","0","0"]'::jsonb, '3', '2전력계법에 의한 3상 유효 전력 $P = P_1 + P_2 = 200 + 200 = 400[W]$');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 4, '$0.2[\Omega]$의 컨덕턴스 2개를 직렬로 접��하여 $3[A]$의 전류를 흘리려면 몇 $[V]$의 전압을 공급하면 되는가?', '["","5","","5"]'::jsonb, '3', '컨덕턴스 $G_1 = 0.2[\Omega]$이므로 저항 $R_1 = \frac{1}{G_1} = \frac{1}{0.2} = 5[\Omega]$. 두 저항이 직렬이므로 합성 저항 $R_0 = R_1 + R_2 = 5 + 5 = 10[\Omega]$. 옴의 법칙에 의해 전압 $V = IR_0 = 3 \times 10 = 30[V]$');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 5, '어떤 교류 회로의 순시 전압이 $v = \sqrt{2}V \sin\omega t[V]$인 전압에서 $\omega t = \frac{\pi}{6}[rad]$일 때 전압의 실효값은?', '["$100\\sqrt{2}$","$100/\\sqrt{2}$","0","$200\\sqrt{2}$"]'::jsonb, '3', '순시 전압 $v = \sqrt{2}V \sin\omega t[V]$에서 $V$는 실효값을 나타낸다. 주어진 그림의 전압 파형에서 최댓값은 $200\sqrt{2}[V]$이므로 실효값 $V = \frac{200\sqrt{2}}{\sqrt{2}} = 200[V]$이다. ($\omega t = \frac{\pi}{6}$는 순간값을 구할 때 사용된다.)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 6, '다음 중 어떤 법칙을 설명한 것인가? 전류가 흐르려고 하면 코일에 전류의 흐름을 방해한다. 또, 전류가 감소하면 이를 계속 유지하려고 하는 성질이 있다.', '["쿨롱의 법칙","렌츠의 법칙","패러데이의 법칙","플레밍의 오른손 법칙"]'::jsonb, '2', '렌츠의 법칙은 유도 기전력의 방향을 정의한 법칙으로 코일에 유도되는 기전력의 방향은 자속의 증가 또는 감소(전류의 증가 또는 감소)를 방해하는 방향으로 발생한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 7, '다음 그림과 같은 $R-C$ 병렬 회로의 위상각 $\theta$는?', '["$\\tan^{-1}\\frac{\\omega C}{R}$","$\\tan^{-1}\\omega CR$","$\\tan^{-1}\\frac{R}{\\omega C}$","$\\tan^{-1}\\frac{1}{\\omega CR}$"]'::jsonb, '2', '$R-C$ 병렬 회로의 위상각 $\theta = \tan^{-1}\frac{I_C}{I_R} = \tan^{-1}\frac{V/X_C}{V/R} = \tan^{-1}\frac{R}{X_C} = \tan^{-1}\omega CR$');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 8, '진공 중에 $10[\mu C]$과 $20[\mu C]$의 점전하를 $1[m]$의 거리로 놓았을 때 작용하는 힘 $[N]$은?', '["$18 \\times 10^{-1}$","$2 \\times 10^{-2}$","$9.8 \\times 10^{-9}$","$9.8 \\times 10^{-10}$"]'::jsonb, '1', '쿨롱의 법칙: 대전된 두 전하 사이에 작용하는 힘의 세기 $F = \frac{1}{4\pi\epsilon_0}\frac{Q_1 Q_2}{r^2} = 9 \times 10^9 \times \frac{10 \times 10^{-6} \times 20 \times 10^{-6}}{1^2} = 18 \times 10^{-1}[N]$');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 9, '다음 그림과 같은 회로에서 $a-b$ 간에 $E[V]$의 전압을 가하여 일정하게 하고, 스위치 $S$를 닫았을 때의 전전류 $I[A]$가 단기 전전류의 3배가 되었다면 저항 $R_x$의 값은 약 몇 $[\Omega]$인가?', '["73","4","6","88"]'::jsonb, '1', '스��치 $S$가 열렸을 때 (단기 전전류 $I_s$): $R_{eq,open} = 8 + 3 = 11[\Omega]$이므로 $I_s = \frac{E}{11}[A]$. 스위치 $S$를 닫았을 때 (전류 $I$): $8[\Omega]$과 $R_x[\Omega]$이 병렬 연결되고 이 조합이 $3[\Omega]$과 직렬 연결되므로 $R_{eq,closed} = 3 + \frac{8R_x}{8+R_x}[\Omega]$. 따라서 $I = \frac{E}{3 + \frac{8R_x}{8+R_x}}[A]$. 주어진 조건 $I = 3I_s$에 대입하면 $\frac{E}{3 + \frac{8R_x}{8+R_x}} = 3 \times \frac{E}{11}$. 양변에서 $E$를 소거하고 정리하면 $11 = 3(3 + \frac{8R_x}{8+R_x}) \Rightarrow 11 = 9 + \frac{24R_x}{8+R_x} \Rightarrow 2 = \frac{24R_x}{8+R_x} \Rightarrow 2(8+R_x) = 24R_x \Rightarrow 16 + 2R_x = 24R_x \Rightarrow 16 = 22R_x \Rightarrow R_x = \frac{16}{22} = \frac{8}{11} \approx 0.727[\Omega]$.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 10, '공기 중에서 $m[Wb]$의 자극으로부터 나오는 자속수는?', '["$\\frac{m}{\\mu_0}$","$\\frac{\\mu_0}{m}$","$m$","$\\frac{m}{4\\pi\\mu_0}$"]'::jsonb, '1', '자속의 총수 $\phi = m[Wb]$이므로 자력선수의 총수 = $\frac{m}{\mu_0}$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 11, '평형 3상 회로에서 1상의 소비 전력이 $P[W]$라면, 3상 회로 전체 소비 전력은 $P[W]$은?', '["$2P$","$\\sqrt{2}P$","$3P$","$\\sqrt{3}P$"]'::jsonb, '3', '평형 3상 회로의 전체 소비 전력은 1상 소비 전력의 3배이다. 즉, $P_{total} = 3P$.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 12, '영구 자석의 재료로서 적당한 것은?', '["잔류 자기가 작고 보자력이 큰 것","잔류 자기가 크고 보자력이 큰 것","잔류 자기가 크고 보자력이 작은 것","잔류 자기가 작고 보자력이 작은 것"]'::jsonb, '2', '영구 자석은 잔류 자기가 크고 보자력이 모두 큰 재료를 사용한다. 전자기석은 잔류 자기는 크고 보자력은 작은 재료를 사용한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 13, '1차 전지로 가장 많이 사용되는 것은?', '["니켈-카드뮴 전지","연료 전지","망간 건전지","납축전지"]'::jsonb, '3', '망간 건전지는 대표적인 1차 전지로서, 음극은 아연, 양극은 이산화망간을 사용한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 14, '플레밍의 왼손 법칙에서 전류의 방향을 나타내는 손가락은?', '["엄지","검지","중지","약지"]'::jsonb, '3', '플레밍의 왼손 법칙에서 엄지는 힘($F$)의 방향, 검지는 자속 밀도($B$)의 방향, 중지는 전류($I$)의 방향을 나타낸다. ($F = IBl\sin\theta[N]$)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 15, '$3[kW]$의 전열기를 1시간 동안 사용할 때 발생하는 열량은 몇 $[kcal]$인가?', '["","80","860",",580"]'::jsonb, '4', '전력량 $H = P \cdot t[kWh]$를 열량으로 환산할 때 $1[kWh] = 860[kcal]$이다. 따라서 $3[kW]$ 전열기를 1시간 사용하면 $3[kWh] = 3 \times 860 = 2,580[kcal]$의 열량이 발생한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 16, '어느 회로의 전류가 다음과 같을 때, 이 회로에 대한 실효값은 몇 $[A]$인가? $i = 3 + 10\sqrt{2}\sin(\omega t - \frac{\pi}{6}) + 5\sqrt{2}\sin(3\omega t - \frac{\pi}{3})[A]$', '["6","2","2","8.3"]'::jsonb, '1', '비정현파의 실효값은 각 성분 실효값의 제곱의 합의 제곱근으로 구한다. $I = \sqrt{I_0^2 + I_1^2 + I_3^2}$ 여기서 $I_0 = 3[A]$, $I_1 = \frac{10\sqrt{2}}{\sqrt{2}} = 10[A]$, $I_3 = \frac{5\sqrt{2}}{\sqrt{2}} = 5[A]$이다. 따라서 $I = \sqrt{3^2 + 10^2 + 5^2} = \sqrt{9 + 100 + 25} = \sqrt{134} \approx 11.57 \approx 11.6[A]$');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 17, '다음 설명 중 틀린 것은?', '["같은 부��의 전하끼리는 반발력이 생긴다.","정전 유도에 의하여 작용하는 힘은 반발력이다.","정전 용량이란 콘덴서가 전하를 축적하는 능력을 말한다.","콘덴서에 전압을 가하는 순간은 콘덴서는 단락 상태가 된다."]'::jsonb, '2', '정전 유도에 의하여 작용하는 힘은 서로 반대 극성의 전하에 의한 힘이므로 흡인력이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 18, '비유전율이 2.5인 유전체 내부의 전속 밀도가 $2 \times 10^{-6}[C/m^2]$ 되는 점의 전장의 세기는 약 몇 $[V/m]$인가?', '["$18 \\times 10^4$","$9 \\times 10^4$","$3.6 \\times 10^4$","$3.6 \\times 10^{-4}$"]'::jsonb, '2', '전속 밀도 $D = \epsilon E[C/m^2]$이므로 전계의 세기는 다음과 같다. $E = \frac{D}{\epsilon} = \frac{D}{\epsilon_0 \epsilon_s} = \frac{2 \times 10^{-6}}{8.855 \times 10^{-12} \times 2.5} \approx 9.03 \times 10^4[V/m]$. 이는 $9 \times 10^4[V/m]$에 가장 가깝다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 19, '전력량 $1[Wh]$와 그 의미가 같은 것은?', '["$1[C]$","$1[J]$","$3,600[C]$","$3,600[J]$"]'::jsonb, '4', '전력량 $W = P \cdot t$. $1[Wh]$는 $1[W]$의 전력을 1시간 동안 사용했을 때의 에너지량이다. $1[h] = 3,600[s]$이므로 $1[Wh] = 1[W] \times 3,600[s] = 3,600[Ws] = 3,600[J]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 20, '전기관선에 대한 설명으로 틀린 것은?', '["같은 전기관선은 흡입한다.","전기관선은 서로 교차하지 않는다.","전기관선은 도체의 표면에 수직으로 흡입한다.","전기관선은 양전하의 표면에서 나와서 음전하의 표면에서 끝난다."]'::jsonb, '1', '전기관선은 같은 극성의 전하에서 서로 반발하며, 다른 극성의 전하에서는 흡인한다. 따라서 같은 전기관선은 흡입하지 않는다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 21, '3상 유도 전동기의 정격 전압을 $V_1$[V], 출력 $P$[kW], 1차 전류 $I_1$[A], 역률 $\cos\theta$를 나타내는 식은?', '["$\\frac{P \\times 10^3}{3V_1I_1 \\cos\\theta} \\times 100[\\%]$","$\\frac{P \\times 10^3}{\\sqrt{3}V_1I_1 \\cos\\theta} \\times 100[\\%]$","$\\frac{\\sqrt{3}P \\times 10^3}{V_1I_1 \\cos\\theta} \\times 100[\\%]$","$\\frac{P \\times 10^3}{\\sqrt{3}V_1I_1 \\cos\\theta} \\times 100[\\%]$"]'::jsonb, '2', '유도 전동기의 효율 $\eta = \frac{\text{출력}}{\text{입력}} \times 100[\%]$ 이므로 입력 $P_1 = \sqrt{3}V_1I_1 \cos\theta$[W]이다. 따라서 $\eta = \frac{P \times 10^3}{\sqrt{3}V_1I_1 \cos\theta} \times 100[\%]$ 이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 22, '6극 36슬롯 3상 동기 발전기의 매극 매상 슬롯수는?', '["","","","5"]'::jsonb, '1', '매극 매상 슬롯수 = $\frac{\text{총 슬롯수}}{\text{극수} \times \text{상수}} = \frac{36}{6 \times 3} = 2$');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 23, '주파수 $60$[Hz]인 회로에 접속되어 슬립 $0.03$[Hz], 회전수 $1,164$[rpm]으로 회전하고 있는 유도 전동기의 극수는?', '["","6","8",""]'::jsonb, '2', '동기 속도 $N_s = \frac{N}{1-s} = \frac{1,164}{1-0.03} = 1,200$[rpm]이다. 극수 $P = \frac{120f}{N_s} = \frac{120 \times 60}{1,200} = 6$[극]이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 24, '그림은 트랜지스터의 스위칭 작용에 의한 직류 전동기의 속도 제어 회로이다. 전동기의 속도가 $N = K \frac{V_a - I_a R_a}{\Phi}$[rpm]이라 할 때, 이 회로에서 사용한 전동기의 속도 제어법은?', '["전압 제어","계자 제어","저항 제어","주파수 제어"]'::jsonb, '1', '직류 전동기의 속도 제어는 전압 제어, 계자 제어, 저항 제어가 있다. 그림은 전압을 가변하여 속도를 제어하는 전압 제어 방식이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 25, '직류 전동기의 최저 절연 저항[M$\Omega$]은?', '["$1,000 + \\text{정격 출력}[\\text{kW}]$","$1,000 + \\text{정격 입력}[\\text{kW}]$","$1 + \\text{정격 입력}[\\text{kW}]$","$1 + \\text{정격 전압}[\\text{V}]$"]'::jsonb, '3', '직류 전동기의 최저 절연 저항은 $1 + \text{정격 입력}[\text{kW}]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 26, '동기 발전기의 병렬 운전 중 기전력의 크기가 다를 경우 나타나는 현상이 아닌 것은?', '["권선이 가열된다.","동기화력이 생긴다.","무효 순환 전류가 흐른다.","고압측에 감자 작용이 생긴다."]'::jsonb, '2', '동기 발전기의 병렬 운전 조건 중 기전력의 크기가 다를 경우 무효 순환 전류가 흐르고 권선이 가열된다. 동기화력은 기전력의 위상이 다를 때 발생한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 27, '전압을 일정하게 유지하기 위해서 이용되는 다이오드는?', '["발광 다이오드","포토 다이오드","제너 다이오드","바리스터 다이오드"]'::jsonb, '3', '제너 다이오드는 전압을 일정하게 유지해 주는 정전압 다이오드이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 28, '변압기의 무부하 시험, 단락 시험에서 구할 수 없는 것은?', '["동손","철손","절연 내력","변압기 변동률"]'::jsonb, '3', '변압기의 무부하 시험으로는 철손과 여자 전류를, 단락 시험으로는 동손과 임피던스 전압을 구할 수 있다. 절연 내력은 이 시험들로 직접 구할 수 없다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 29, '대전류·고전압의 전기를 제어할 수 있는 소자는?', '["FET","Diode","Triac","IGBT"]'::jsonb, '4', 'IGBT(Insulated Gate Bipolar Transistor)는 고속도, 고효율의 전력 시스템에서 널리 사용되며 $300$[V] 이상의 대전류, 고전압 제어 전원용 반도체이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 30, '1차 권수 $6,000$, 2차 권수 $200$인 변압기의 전압비는?', '["","","60","90"]'::jsonb, '2', '변압기의 권수비 $a = \frac{N_1}{N_2} = \frac{6,000}{200} = 30$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 31, '주파수 $60$[Hz]인 3상 발전용 원동기인 터빈 발전기의 최고 속도[rpm]는?', '[",800",",400",",600",",800"]'::jsonb, '3', '발전기의 회전 속도 $N = \frac{120f}{P}$[rpm]이다. 최고 속도는 극수가 가장 작을 때(2극) 발생하므로 $N = \frac{120 \times 60}{2} = 3,600$[rpm]이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 32, '변압기의 권수비가 $60$일 때 2차측 저항이 $0.1$[$\Omega$]이다. 이것을 1차로 환산하면 몇 [$\Omega$]인가?', '["0","60","90","0"]'::jsonb, '2', '변압기의 권수비 $a = \sqrt{\frac{R_1}{R_2}}$ 이므로 $R_1 = a^2 R_2 = 60^2 \times 0.1 = 360$[$\Omega$]이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 33, '직류 파형의 파형률이 극수에 관계없이 병렬 회로수 $a$는 얼마인가?', '["","","","8"]'::jsonb, '2', '직류 파형의 병렬 회로수는 극수와 상관없이 항상 2이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 34, '단락비가 큰 동기 발전기에 대한 설명으로 틀린 것은?', '["단락 전류가 크다.","동기 임피던스가 작다.","전기자 반작용이 크다.","공극이 크고 전압 변동률이 작다."]'::jsonb, '3', '단락비가 큰 동기 발전기는 동기 임피던스가 작고, 전기자 반작용이 작으며, 공극이 크고, 전압 변동률이 작아 안정도가 좋다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 35, '변압기 철심의 철심에서 실제 철의 단면적과 철심의 유효 단면적의 비를 무엇이라고 하는가?', '["권수비","변류비","적층률","비율"]'::jsonb, '3', '철의 단면적과 철심의 유효 단면적의 비를 적층률이라 하며, 일반적인 변압기는 그 비율이 $96$[\%] 정도 된다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 36, '특성 곡선을 통해 그림과 같은 기동 특성을 가지는 전동기는? (단, 곡선 ⑦~⑧은 기동 단계에 대한 토크 특성 곡선이다.)', '["반발 기동형 유도 전동기","상 농형 유도 전동기","상 권선형 유도 전동기","상 권선형 유도 전동기"]'::jsonb, '1', '단상 유도 전동기의 토크 크기 순서는 반발 기동형 > 반발 유도형 > 콘덴서 기동형 > 분상 기동형 > 셰이딩 코일형이다. 그림의 특성 곡선은 기동 토크가 큰 반발 기동형 유도 전동기의 특성이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 37, '고장 시의 불평형 차전류가 평형 전류의 $2$배 이상이 되었을 때 동작하는 계전기는?', '["과전압 계전기","과전류 계전기","비율 차동 계전기","지락 계전기"]'::jsonb, '3', '비율 차동 계전기는 내부 고장 발생 시 고·저압 측에 설치한 CT 2차측의 역상 코일에 흐르는 전류차가 일정 비율 이상이 되었을 때 동작하는 방식의 계전기이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 38, '단상 유도 전동기의 기동 방법 중 기동 토크가 가장 큰 것은?', '["반발 기동형","분상 기동형","반발 유도형","콘덴서 기동형"]'::jsonb, '1', '단상 유도 전동기의 토크 크기 순서: 반발 기동형 > 반발 유도형 > 콘덴서 기동형 > 분상 기동형 > 셰이딩 코일형');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 39, '변압기 변동률 $e$의 식은? (단, 정격 전압 $V_n$[V], 무부하 전압 $V_0$[V]이다.)', '["$e = \\frac{V_0 - V_n}{V_0} \\times 100[\\%]$","$e = \\frac{V_n - V_0}{V_n} \\times 100[\\%]$","$e = \\frac{V_0 - V_n}{V_n} \\times 100[\\%]$","$e = \\frac{V_n - V_0}{V_0} \\times 100[\\%]$"]'::jsonb, '3', '변압기 변동률 $e = \frac{V_0 - V_n}{V_n} \times 100[\%]$이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 40, '계자 권선이 전기자 권선이 있지 않은 직류기는?', '["직권기","분권기","타여자","복여자"]'::jsonb, '3', '타여자 발전기는 발전기 외부의 별도의 다른 직류 전압원에서 여자 전류를 공급하여 계자를 여자시키는 방식의 발전기이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 41, '$450/750[V]$ 일반용 단심 비닐 절연 전선의 허용 전류는?', '["$N R I$","$N F$","$N F I$","$N R$"]'::jsonb, '4', '해설: $450/750[V]$ 일반용 단심 비닐 절연 전선
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 42, '다음 중 $220[V]$ 3상 유도 전동기 2차 측에 인가할 절연 저항 ��험 전압은 $V$로 하여야 하는가?', '["$330$","$500$","$750$","$1,050$"]'::jsonb, '2', '해설: 발전기, $7,000[V]$ 이하 $1.5$배(최저 $500[V]$)
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 43, '금속관 공사에서 사용되는 후강 전선관의 규격이 아닌 것은?', '["$16$","$28$","$36$","$50$"]'::jsonb, '3', '해설: 후강 전선관의 종류: $16, 22, 28, 36, 42, 54, 70, 82, 92, 104[mm]$');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 44, '금속관 구부리기에 있어 그 안쪽의 반지름은 관 안지름의 몇 배 이상이 되어야 하는가?', '["$1$","$4$","$8$","$10$"]'::jsonb, '2', '해설: 금속관 구부리기는 그 굴곡 반경은 관내경의 $6$배 이상으로 하여야 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 45, '피뢰기의 약호는?', '["$L A$","$S A$","$P F$","$C O S$"]'::jsonb, '1', '해설: 피뢰기($L A$): 낙뢰 시 발생하는 이상 전압으로부터 기기를 보호하기 위한 장치');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 46, '차단기 기호 중 "$O C B$"는?', '["진공 차단기","기중 차단기","자기 차단기","유입 차단기"]'::jsonb, '4', '해설: 유입 차단기($O C B$: Oil Circuit Breaker): 아크 소호 시 절연유 분해 가스의 흡부력을 이용하여 차단');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 47, '한국전기설비규정에서 교통 신호등 회로의 사용 전압이 몇 $[V]$를 초과하는 경우에는 지락 발생 시 자동으로 전로를 차단하는 장치를 시설하여야 하는가?', '["$50$","$100$","$150$","$200$"]'::jsonb, '3', '해설: 교통 신호등 회로의 사용 전압이 $150[V]$를 초과하는 경우에 전로에 지락이 발생했을 때 자동으로 전로를 차단하는 차단기를 시설하여야 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 48, '케이블 공사에서 비닐 외장 케이블을 조영재의 옆면에 따라 시설하는 경우 지지점 간 거리는 몇 $[m]$인가?', '["$1.0$","$1.5$","$2.0$","$2.5$"]'::jsonb, '3', '해설: 케이블을 조영재 옆면 또는 아랫면에 따라 지지하는 경우 지지점 간 거리는 $2[m]$ 이하마다 지지한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 49, '누전 차단기의 설치 목적은 무엇인가?', '["단락","과부하","지락","과전류"]'::jsonb, '3', '해설: 누전 차단기는 전로에 지락이 생겼을 경우에 부하, 금속제 외함 등에 발생하는 고장 전류를 검출하여 고장 부분을 차단하고 인체 감전으로부터 보호하는 장치이다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 50, '금속 간 조영재에 붙이는 경우 지지점 간의 거리는 최대 몇 $[m]$ 이하로 하여야 하는가?', '["$1.5$","$2.0$","$3.0$","$3.5$"]'::jsonb, '2', '해설: 덕트의 지지점 간 거리는 $3[m]$ 이하로 할 것.
(단, 취급자 이외에는 출입할 수 없는 곳에서 수직으로 설치하는 경우 $6[m]$ 이하까지도 가능)');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 51, '정연물에서 폴리에틸렌($X L P E$)과 에틸렌 프로필렌 고무 혼합물($E P R$)의 허용 온도는 몇 $[^{\circ}C]$인가?', '["$70$ (전선)","$90$ (전선)","$95$ (전선)","$105$ (전선)"]'::jsonb, '3', '해설: 가교 폴리에틸렌($X L P E$), 에틸렌 프로���렌 고무 혼합물($E P R$) 절연 전선의 허용 온도: $90[^{\circ}C]$');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 52, '완전 확산면은 어느 방향에서 보아도 무엇이 동일한가?', '["광속","휘도","조도","광도"]'::jsonb, '2', '해설: 완전 확산 광원은 어떠한 방향에서 바라 볼 때 단위 투영 면적당 빛이 나는 정도를 말하며 어느 방향에서나 휘도가 동일한 표면을 완전 확산면이라 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 53, '합성 수지 전선관 공사에서 관 상호 간 접속에 필요한 부속품은?', '["커플링","컨넥터","노멀 밴드","엔트런스 캡"]'::jsonb, '1', '해설: 커플링: 합성 수지관 상호 접속하는 기구');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 54, '배전반을 나타내는 그림 기호는?', '["image of a square with a diagonal line)","image of a square with a vertical line)","image of a square with a horizontal line)","image of a square with \u0027S\u0027 inside)"]'::jsonb, '1', '해설: ① 분전반
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 55, '조명 공학에서 사용되는 칸델라($c d$)는 무엇의 단위인가?', '["광도","조도","광속","광량"]'::jsonb, '1', '해설: 광도: 광원의 어느 방향에 대한 단위 입체각당 광속
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 56, '옥내 배선을 합성 수지관 공사에 의하여 시설할 때 단선의 최대 단면적은 몇 $[mm^2]$인가?', '["$4$","$6$","$10$","$16$"]'::jsonb, '3', '해설: 합성 수지관 공사 시 사용 전선은 연선을 사용하되, 단선일 경우 $10[mm^2]$ 이하로 가능하다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 57, '다음 중 배선 기구가 아닌 것은?', '["배전반","개폐기","배선용 차단기","전등 기구"]'::jsonb, '4', '해설: 배선 기구: 개폐기, 과전류 차단기, 접속기 기타 전등 기구와 같은 것을 말한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 58, '한국전기설비규정에서 가공 전선로의 지지물에 하중이 가하여지는 경우 그 하중을 받는 지지물의 기초 안전율은 얼마 이상으로 하여야 하는가?', '["$0.5$","$1$","$1.5$","$2$"]'::jsonb, '4', '해설: 가공 전선로의 지지물에 하중이 가하여지는 경우 그 하중을 받는 지지물의 기초 안전율은 $2.0$ 이상으로 하여야 한다.');
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 59, '이동 행선용 옥내 배선, 전구선 또는 이동 전선의 전압은 몇 $[V]$ 이하인가?', '["$400$","$440$","$450$","$750$"]'::jsonb, '1', '해설: 이동 행선장 시설 원칙
INSERT INTO public.dukigo_exam_questions (subject_id, exam_year, exam_round, question_no, question_text, options, correct_answer, explanation) VALUES ('ELECTRICITY', 2016, 4, 60, '구리 전선과 전기 기계 기구 단자를 접속하는 경우에 진동 등으로 인하여 헐거워질 염려가 있는 곳에는 어떤 것을 사용하여 접속하여야 하는가?', '["정 슬리브를 끼운다.","평와서 $2$개를 끼운다.","코드 패스너를 끼운다.","스프링 와셔를 끼운다."]'::jsonb, '4', '해설: 진동으로 인하여 단자가 헐거워질 우려가 있는 곳은 이중 너트나 스프링 와셔를 사용한다.');
